import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import {
  DEBUG_PREFIX,
  DEBUG_TIMING_ON,
  ENGINE_ORIGIN,
  ESCALATION_TOAST_MS,
  LOOP_BREAKER_COMMAND_DESCRIPTION,
  PERSON_PROMPT_KINDS,
  SKELETON_REPLY,
  TIMELINE_CAP,
} from './adapter/constants.ts'
import {
  flushStats,
  loadSettings,
  onConversationReset,
  onPersonPrompt,
  onTurnComplete,
} from './adapter/lifecycle.ts'
import { logOnce, observeToolCall, reportOverhead } from './adapter/observer.ts'
import type { EnginePort } from './adapter/ports.ts'
import { settingsFrom } from './adapter/settings.ts'
import { addStats, emptyStats } from './adapter/stats.ts'

// Session state, declared in types/index.d.ts. `plugin` and `key` are quoted
// literals in consts of this file: validate reads state references only here.
const detectionAtom = atom({ plugin: 'loop-breaker', key: 'detection' } as const, ``)
const alertAtom = atom({ plugin: 'loop-breaker', key: 'alert' } as const, null)
const timelineAtom = atom({ plugin: 'loop-breaker', key: 'timeline' } as const, [])
const mainTurnIdAtom = atom({ plugin: 'loop-breaker', key: 'mainTurnId' } as const, null)
const pendingStatsAtom = atom(
  { plugin: 'loop-breaker', key: 'pendingStats' } as const,
  emptyStats(),
)

/**
 * The engine port over `$`: every engine call Loop Breaker makes, each a
 * literal `$.noun.method(...)` call. It lives in this file because
 * `claude plugin validate` follows `$` only into functions declared here;
 * the adapter modules receive this port instead of `$`.
 */
function portFor($: EngineInterface): EnginePort {
  return {
    now: () => $.clock.now(),
    updateDetection: async change => {
      await update($, detectionAtom, change)
    },
    log: text => {
      $.ui.log(`${DEBUG_PREFIX} ${text}`, { to: `debug` })
    },
    toast: text => {
      $.ui.toast(text, { timeoutMs: ESCALATION_TOAST_MS })
    },
    alertedSignatures: async () => {
      const timeline = await read($, timelineAtom)
      return new Set(timeline.map(entry => entry.signature))
    },
    agentName: async agentId => {
      try {
        const agent = (await $.agent.list()).find(candidate => candidate.id === agentId)
        return agent === undefined ? null : (agent.name ?? agent.type)
      } catch {
        return null
      }
    },
    setAlert: async alert => {
      await update($, alertAtom, () => alert)
    },
    clearAlertFor: async signatures => {
      await update($, alertAtom, current =>
        current !== null && signatures.includes(current.signature) ? null : current,
      )
    },
    addTimeline: async entries => {
      if (entries.length === 0) return
      await update($, timelineAtom, timeline => [...timeline, ...entries].slice(-TIMELINE_CAP))
    },
    clearTimeline: async () => {
      await update($, timelineAtom, () => [])
    },
    addPendingStats: async delta => {
      await update($, pendingStatsAtom, pending => addStats(pending, delta))
    },
    takePendingStats: async () => {
      let taken = emptyStats()
      await update($, pendingStatsAtom, pending => {
        taken = pending
        return emptyStats()
      })
      return taken
    },
    appendNote: async (text, agentId) => {
      await $.session.append({
        message: { type: `user`, content: [{ type: `text`, text }] },
        ...(agentId === undefined ? {} : { agentId }),
      })
    },
    setMainTurnId: async turnId => {
      await update($, mainTurnIdAtom, () => turnId)
    },
    storeGet: key => $.store.get(key),
    storeSet: (key, value) => $.store.set(key, value),
    // A literal name: validate lists the variables a module reads.
    isDebugTimingOn: async () => (await $.env.get('LOOP_BREAKER_DEBUG')) === DEBUG_TIMING_ON,
  }
}

/**
 * Loop Breaker's hooks module: the only entry point the engine loads.
 *
 * It wires engine events to the adapter layer and holds no logic of its own
 * beyond the engine port above. Detection lives in `core/` (pure, no `$`),
 * orchestration in `adapter/` (through the port, never `$`), and drawing in
 * `ui/`. This keeps the core testable in Node and keeps every `$` call
 * literal, which `claude plugin validate` relies on.
 *
 * Every hook here is fail-open: its own work is wrapped so that an error is
 * logged once (debug log) and the engine's behaviour goes on unchanged. Loop
 * Breaker never denies a call, never rewrites an input, and changes a result
 * only by appending its nudge for the model.
 *
 * Engine-analysed literals: the command's registration `name` and the
 * `command.run` matcher are plain quoted strings ('loop-breaker'), not template
 * literals or constants, which deliberately breaks the backtick string style.
 * `claude plugin validate` only recognises a hook that answers its own
 * command when both are quoted literals; otherwise it treats the hook as a
 * gate on every command (Phase 1 spike finding). `LOOP_BREAKER_COMMAND` in
 * `adapter/constants.ts` mirrors the name.
 */
export const register: Register = (on, options) => {
  // Re-read on every load: a `/config` change reloads the module with new options.
  let settings = settingsFrom(options)

  on(`session.start`, async ($, e, next) => {
    const port = portFor($)
    try {
      await $.command.register({
        // Quoted literal, not a template or constant: required by validate (see above).
        name: 'loop-breaker',
        description: LOOP_BREAKER_COMMAND_DESCRIPTION,
        immediate: true,
      })
    } catch (error) {
      logOnce(port, `command registration`, error)
    }
    try {
      settings = await loadSettings(port, settingsFrom(options))
    } catch (error) {
      logOnce(port, `session.start`, error)
    }
    return next(e)
  })

  // `/clear`, a resume or a fork starts a new conversation without a new `session.start`.
  on(`classic.SessionStart`, { source: [`clear`, `resume`, `fork`] }, async ($, e, next) => {
    const port = portFor($)
    try {
      await onConversationReset(port)
    } catch (error) {
      logOnce(port, `classic.SessionStart`, error)
    }
    return next(e)
  })

  // One store write, nothing slow: `session.end` hooks share a 1.5 s budget.
  on(`session.end`, async ($, e, next) => {
    const port = portFor($)
    try {
      if (settings.isTimingOn) reportOverhead(port)
      await flushStats(port)
    } catch (error) {
      logOnce(port, `session.end`, error)
    }
    return next(e)
  })

  // The person's own prompt resets every streak; a notification or a peer's message does not.
  // Observing only: the prompt goes in first, and a dropped prompt resets nothing (review I1).
  on(`prompt.submit`, async ($, e, next) => {
    const entered = await next(e)
    if (entered.drop === undefined && PERSON_PROMPT_KINDS.has(e.origin.kind)) {
      const port = portFor($)
      try {
        await onPersonPrompt(port)
      } catch (error) {
        logOnce(port, `prompt.submit`, error)
      }
    }
    return entered
  })

  on(`turn.start`, async ($, e, next) => {
    const port = portFor($)
    try {
      await port.setMainTurnId(e.turnId)
    } catch (error) {
      logOnce(port, `turn.start`, error)
    }
    return next(e)
  })

  // The main loop's turn only: a subagent's turn ending neither frees the budget nor flushes.
  on(`turn.complete`, async ($, e, next) => {
    const completed = await next(e)
    if (e.agentId === undefined) {
      const port = portFor($)
      try {
        await onTurnComplete(port)
      } catch (error) {
        logOnce(port, `turn.complete`, error)
      }
    }
    return completed
  })

  // The observer: the tool always runs first; only the model's own calls are counted (R10).
  on(`tool.call`, async ($, e, next) => {
    if (next.origin.plugin !== ENGINE_ORIGIN) return next(e)
    const startedAt = await $.clock.now()
    const ran = await next(e)
    return observeToolCall(portFor($), e, ran, startedAt, settings)
  }).catch((_$, e, next) => next(e))

  // Quoted literal matcher, as above. It must equal the registered name.
  on(`command.run`, { command: 'loop-breaker' }, () => ({ text: SKELETON_REPLY }))
}

