/**
 * Names, keys and limits the adapter layer shares with the engine and the
 * tests, kept in one module so no literal is repeated.
 */
import type { PromptOrigin } from 'claude-code'

/**
 * The slash command Loop Breaker serves, without its slash.
 *
 * `register.tsx` must spell this name as a plain quoted literal (see the note
 * there), so this constant mirrors it for tests and messages. Keep the two
 * equal. `loops` is not used: Claude Code ships that name and refuses it.
 */
export const LOOP_BREAKER_COMMAND = `loop-breaker`

/** The one line the typeahead and `/help` show for {@link LOOP_BREAKER_COMMAND}. */
export const LOOP_BREAKER_COMMAND_DESCRIPTION = `Loop Breaker: show detected loops, stats and controls`

/** What the command answers until the pane and stats land (Phase 5). */
export const SKELETON_REPLY = `Loop Breaker is active (skeleton).`

/** `next.origin.plugin` of a call the model made (spike R10); other mods' calls are not counted. */
export const ENGINE_ORIGIN = `engine`

/** Store key of the cross-session counts (versioned; counts only, never content). */
export const STATS_STORE_KEY = `stats.v1`

/** Store key of the substrings the person chose to always ignore (versioned). */
export const IGNORE_STORE_KEY = `ignorePatterns.v1`

/** Newest timeline entries kept in session state. */
export const TIMELINE_CAP = 100

/** How long the escalation toast stays, in milliseconds. */
export const ESCALATION_TOAST_MS = 8000

/** Prefix of every debug-log line, so `claude --debug` output is easy to filter. */
export const DEBUG_PREFIX = `loop-breaker:`

/**
 * Prompt origins that are the person's own: their prompt resets every streak.
 * A task notification, a peer's message or a schedule is not the person engaging.
 */
export const PERSON_PROMPT_KINDS: ReadonlySet<PromptOrigin[`kind`]> = new Set([
  `composer`,
  `bridge`,
  `sdk`,
  `slack-ping`,
])

/** Longest error message written to the debug log when a hook's own work fails (no call content). */
export const ERROR_TEXT_CAP = 200

/** The value of `LOOP_BREAKER_DEBUG` that turns on overhead timing (the name is a literal in `register.tsx`). */
export const DEBUG_TIMING_ON = `1`

/** Observed calls between two overhead reports when debug timing is on. */
export const TIMING_REPORT_EVERY = 100

/** Percentiles of the overhead report. */
export const TIMING_PERCENTILES = [0.5, 0.95] as const

