/**
 * What Loop Breaker does at the session's and the turn's edges: load the
 * person's stored choices, reset streaks when the person speaks, reset the
 * per-turn nudge budget, and flush counts to the store. Every function takes
 * the engine port, never `$`.
 */
import { processTurnEnd, processUserPrompt } from '../core/pipeline.ts'
import { emptyDetectionState } from '../core/window.ts'
import { IGNORE_STORE_KEY, STATS_STORE_KEY } from './constants.ts'
import type { EnginePort } from './ports.ts'
import type { Settings } from './settings.ts'
import { withStoredIgnores } from './settings.ts'
import { parseDetection, serializeDetection } from './state.ts'
import { addStats, hasCounts, statsFrom } from './stats.ts'

/**
 * Settings with the store's ignore list and the debug-timing switch read.
 * Overlong `ignoreCommands` entries are reported once in the debug log (ER-5).
 */
export async function loadSettings(port: EnginePort, settings: Settings): Promise<Settings> {
  if (settings.rejectedIgnoreCount > 0) {
    port.log(
      `ignored ${String(settings.rejectedIgnoreCount)} overlong ignoreCommands entries (set in /config)`,
    )
  }
  const stored = await port.storeGet(IGNORE_STORE_KEY)
  return { ...withStoredIgnores(settings, stored), isTimingOn: await port.isDebugTimingOn() }
}

/** The person spoke: every loop's streak starts over and the alert is taken down. */
export async function onPersonPrompt(port: EnginePort): Promise<void> {
  const now = await port.now()
  await port.updateDetection(json =>
    serializeDetection(processUserPrompt(parseDetection(json), now)),
  )
  await port.setAlert(null)
}

/**
 * Adds the session's pending counts to the store's. The store is shared by
 * every session on the machine and get-then-set is not atomic, so the key is
 * read right before the write; a rare lost increment is accepted (the counts
 * are informational). Counts taken but not written are put back for the next flush.
 */
export async function flushStats(port: EnginePort): Promise<void> {
  const taken = await port.takePendingStats()
  if (!hasCounts(taken)) return
  try {
    const stored = statsFrom(await port.storeGet(STATS_STORE_KEY))
    await port.storeSet(STATS_STORE_KEY, addStats(stored, taken))
  } catch (error) {
    await port.addPendingStats(taken)
    throw error
  }
}

/** The main turn ended: the per-turn nudge budget resets and the counts are flushed. */
export async function onTurnComplete(port: EnginePort): Promise<void> {
  await port.updateDetection(json => serializeDetection(processTurnEnd(parseDetection(json))))
  await port.setMainTurnId(null)
  await flushStats(port)
}

/**
 * A new conversation in the same process (`/clear`, a resume, a fork): no
 * `session.start` fires, so detection, the alert and the timeline start over
 * here, whether or not the host kept `$.state` (spike R9 pending). Counts
 * were flushed by `session.end` just before.
 */
export async function onConversationReset(port: EnginePort): Promise<void> {
  await port.updateDetection(() => serializeDetection(emptyDetectionState()))
  await port.setAlert(null)
  await port.clearTimeline()
  await port.setMainTurnId(null)
}

