/**
 * The tool-call observer: runs after the engine answered a call, feeds the
 * core, carries out its decisions, and hands the model's result back with
 * nothing changed but an appended nudge.
 *
 * Fail-open is the rule: any error in here is logged once and the engine's
 * result is returned as it came. The observer never denies a call and never
 * rewrites its input (in auto mode a rewritten input is denied).
 *
 * The nudge comes first. It is built from the decisions before anything else
 * is awaited, and no later failure (the timeline, the alert, the counts, a
 * refusal's note) can cost the model its note (Phase 4 review, I2).
 */
import type { ToolCallInput, ToolCallResult } from 'claude-code'

import { MAIN_LOOP } from '../core/constants.ts'
import { processRecord, recordFor } from '../core/pipeline.ts'
import type { PipelineStep } from '../core/pipeline.ts'
import type { Decision } from '../core/types.ts'
import { ERROR_TEXT_CAP, TIMING_PERCENTILES, TIMING_REPORT_EVERY } from './constants.ts'
import { observationOf } from './observation.ts'
import type { EffectsPlan } from './plan.ts'
import { planFor } from './plan.ts'
import type { EnginePort } from './ports.ts'
import type { Settings } from './settings.ts'
import type { DetectionRead } from './state.ts'
import { readDetection, serializeDetection } from './state.ts'

/** Failures already logged in this load: each kind is logged once, not per call. */
const loggedFailures = new Set<string>()

/**
 * Overheads measured since the last report, in milliseconds (debug timing
 * only). Measured from the result's arrival to the observer's return: the one
 * clock read before the tool runs is not included.
 */
const overheads: number[] = []

/** Logs a failure of `site` once per load, without any call content. */
export function logOnce(port: EnginePort, site: string, error: unknown): void {
  if (loggedFailures.has(site)) return
  loggedFailures.add(site)
  const reason =
    error instanceof Error ? `${error.name}: ${error.message.slice(0, ERROR_TEXT_CAP)}` : `unknown`
  port.log(`${site} failed and was skipped (fail-open): ${reason}`)
}

/** The value at fraction `percentile` of sorted `values`. */
function percentileOf(values: readonly number[], percentile: number): number {
  const sorted = [...values].sort((a, b) => a - b)
  return sorted[Math.min(sorted.length - 1, Math.floor(percentile * sorted.length))] ?? 0
}

/** Logs the percentiles of the overheads measured so far, then starts over (debug timing only). */
export function reportOverhead(port: EnginePort): void {
  if (overheads.length === 0) return
  const report = TIMING_PERCENTILES.map(
    percentile => `p${String(percentile * 100)} ${String(percentileOf(overheads, percentile))} ms`,
  ).join(`, `)
  port.log(`observer overhead over ${String(overheads.length)} calls: ${report}`)
  overheads.length = 0
}

/** Records one call's overhead; every `TIMING_REPORT_EVERY` calls, logs the percentiles. */
async function recordOverhead(port: EnginePort, since: number): Promise<void> {
  overheads.push((await port.now()) - since)
  if (overheads.length >= TIMING_REPORT_EVERY) reportOverhead(port)
}

/** The notes for the model among the decisions. */
function nudgesOf(decisions: readonly Decision[]): readonly string[] {
  return decisions.flatMap(decision => (decision.kind === `nudge` ? [decision.text] : []))
}

/**
 * The result with the nudges attached for the model: appended to `context`
 * (spike R1), or, for a refused call whose result takes none, appended as a
 * row of its own (spike R1b). A failed append is logged; the refusal itself
 * is returned as it came either way.
 */
async function withNudges(
  ran: ToolCallResult,
  nudges: readonly string[],
  port: EnginePort,
  agentId: string | undefined,
): Promise<ToolCallResult> {
  if (nudges.length === 0) return ran
  if (ran.deny === undefined) return { ...ran, context: [...(ran.context ?? []), ...nudges] }
  try {
    for (const note of nudges) await port.appendNote(note, agentId)
  } catch (error) {
    logOnce(port, `refusal note`, error)
  }
  return ran
}

/** Carries out a plan's alert, timeline and counts. */
async function carryOut(port: EnginePort, plan: EffectsPlan, loopId: string): Promise<void> {
  const { escalation } = plan
  if (escalation !== undefined) {
    const agentName = loopId === MAIN_LOOP ? null : await port.agentName(loopId)
    await port.setAlert({ ...escalation, agentName })
    // The engine shows a toast under the plugin's name already.
    port.toast(escalation.title)
  } else if (plan.resolved.length > 0) {
    await port.clearAlertFor(plan.resolved)
  }
  await port.addTimeline(plan.timeline)
  await port.addPendingStats(plan.stats)
}

/** Signatures that already alerted, or none when the timeline can't be read. */
async function alertedOrNone(port: EnginePort): Promise<ReadonlySet<string>> {
  try {
    return await port.alertedSignatures()
  } catch (error) {
    logOnce(port, `timeline read`, error)
    return new Set()
  }
}

/**
 * Observes one finished tool call of the model's. Never throws: on any error
 * the engine's result is returned unchanged.
 *
 * @param startedAt when the call was issued (read before `next`), so calls
 *   issued together count as one attempt
 */
export async function observeToolCall(
  port: EnginePort,
  e: ToolCallInput,
  ran: ToolCallResult,
  startedAt: number,
  settings: Settings,
): Promise<ToolCallResult> {
  try {
    const at = await port.now()
    // Built once, outside the compare-and-swap below: hashing a large file is never repeated.
    const record = recordFor(observationOf(e, ran, { startedAt, at }), settings.config)
    if (record === undefined) return ran
    let step: PipelineStep | undefined
    let read: DetectionRead | undefined
    await port.updateDetection(json => {
      read = readDetection(json)
      step = processRecord(read.state, record, settings.config)
      return serializeDetection(step.state)
    })
    if (read?.wasDiscarded === true)
      port.log(`stored detection state was unreadable and started over`)
    const decisions = step?.decisions ?? []
    if (decisions.length === 0) {
      if (settings.isTimingOn) await recordOverhead(port, at)
      return ran
    }
    const answered = await withNudges(ran, nudgesOf(decisions), port, e.agentId)
    try {
      await carryOut(port, planFor(decisions, at, await alertedOrNone(port)), record.loopId)
    } catch (error) {
      logOnce(port, `decision effects`, error)
    }
    if (settings.isTimingOn) await recordOverhead(port, at)
    return answered
  } catch (error) {
    logOnce(port, `tool.call observer`, error)
    return ran
  }
}

