/**
 * The engine port: everything the adapter needs from Claude Code, as plain
 * functions. `register.tsx` implements it with literal `$` calls, because
 * `claude plugin validate` follows `$` only into functions of that file,
 * never across an import. Every other adapter module takes this port, so it
 * never sees `$` and tests can hand it a fake.
 */
import type {
  LoopBreakerAlert,
  LoopBreakerStats,
  LoopBreakerTimelineEntry,
} from '../../types/index.d.ts'

/** What the adapter does to, and reads from, the engine. */
export interface EnginePort {
  /** The time now, in milliseconds (`$.clock.now`). */
  readonly now: () => Promise<number>
  /** Reads the detection JSON, applies `change`, writes it back (retried on a version miss). */
  readonly updateDetection: (change: (json: string) => string) => Promise<void>
  /** A line in the debug log, never the transcript. */
  readonly log: (text: string) => void
  /** A toast under the plugin's name. */
  readonly toast: (text: string) => void
  /** Signatures that already alerted this session, from the timeline. */
  readonly alertedSignatures: () => Promise<ReadonlySet<string>>
  /** A subagent's name or type, best effort: `null` when unknown. */
  readonly agentName: (agentId: string) => Promise<string | null>
  readonly setAlert: (alert: LoopBreakerAlert | null) => Promise<void>
  /** Takes the alert down when it is about one of `signatures`. */
  readonly clearAlertFor: (signatures: readonly string[]) => Promise<void>
  readonly addTimeline: (entries: readonly LoopBreakerTimelineEntry[]) => Promise<void>
  /** Empties the timeline: a new conversation (`/clear`) starts its own. */
  readonly clearTimeline: () => Promise<void>
  readonly addPendingStats: (delta: LoopBreakerStats) => Promise<void>
  /** Takes the pending counts, leaving zeros behind (one atomic swap). */
  readonly takePendingStats: () => Promise<LoopBreakerStats>
  /** A note for the model on its own row: for a refused call, whose result takes no context. */
  readonly appendNote: (text: string, agentId: string | undefined) => Promise<void>
  readonly setMainTurnId: (turnId: string | null) => Promise<void>
  readonly storeGet: (key: string) => Promise<unknown>
  readonly storeSet: (key: string, value: unknown) => Promise<void>
  /** Whether `LOOP_BREAKER_DEBUG=1` asks for overhead timing in the debug log. */
  readonly isDebugTimingOn: () => Promise<boolean>
}

files.hooks/adapter/settings.ts:
/**
 * What the person configured: the `userConfig` options (`register(on,
 * options)`) plus the substrings they chose to always ignore, kept in the
 * store. Resolved once per load; a `/config` change reloads the module.
 */
import type { PluginOptions } from 'claude-code'

import { parseIgnoreList, resolveConfig } from '../core/config.ts'
import type { DetectorConfig } from '../core/config.ts'
import { IGNORE_ENTRY_MAX_COUNT } from '../core/constants.ts'

/** Everything the hooks read about the person's choices. */
export interface Settings {
  readonly config: DetectorConfig
  /** Whether overhead timing goes to the debug log (`LOOP_BREAKER_DEBUG`). */
  readonly isTimingOn: boolean
  /** `ignoreCommands` entries dropped as overlong: reported once in the debug log (ER-5). */
  readonly rejectedIgnoreCount: number
}

/** Settings from the manifest options alone. */
export function settingsFrom(options: PluginOptions): Settings {
  return {
    config: resolveConfig(options),
    isTimingOn: false,
    rejectedIgnoreCount: parseIgnoreList(options.ignoreCommands).rejected.length,
  }
}

/**
 * Settings with the store's ignore list added. Whatever the store holds is
 * checked: only strings count, overlong ones are dropped, at most
 * `IGNORE_ENTRY_MAX_COUNT`. A damaged value adds nothing.
 */
export function withStoredIgnores(settings: Settings, stored: unknown): Settings {
  if (!Array.isArray(stored)) return settings
  const text = stored
    .filter((entry): entry is string => typeof entry === `string` && !entry.includes(`,`))
    .slice(0, IGNORE_ENTRY_MAX_COUNT)
    .join(`,`)
  const extra = parseIgnoreList(text).entries
  if (extra.length === 0) return settings
  const ignoreCommands = [...new Set([...settings.config.ignoreCommands, ...extra])]
  return { ...settings, config: { ...settings.config, ignoreCommands } }
}

