/**
 * Effectiveness counts: how often Loop Breaker nudged, escalated and
 * stopped, and how often a nudge resolved the loop. Counts only, never a
 * command, an output or a file (non-negotiable: nothing persisted past the
 * session but numbers). Pure functions; the store access is in `lifecycle.ts`.
 */
import type { LoopBreakerStats } from '../../types/index.d.ts'

/** Counts that are all zero. */
export function emptyStats(): LoopBreakerStats {
  return {
    loopsDetected: 0,
    nudges: 0,
    nudgesResolved: 0,
    escalations: 0,
    stops: 0,
    ignores: 0,
    byDetector: {},
  }
}

/** A number field of an unknown record, or 0. */
function countOf(value: unknown, key: string): number {
  if (typeof value !== `object` || value === null) return 0
  const field = (value as Readonly<Record<string, unknown>>)[key]
  return typeof field === `number` && Number.isFinite(field) && field >= 0 ? field : 0
}

/**
 * Counts read back from the store, whatever was there: unknown or damaged
 * fields count as 0, so a bad value can never break a flush.
 */
export function statsFrom(value: unknown): LoopBreakerStats {
  const byDetector: Record<string, { nudges: number; escalations: number }> = {}
  const rawByDetector =
    typeof value === `object` && value !== null
      ? (value as Readonly<Record<string, unknown>>).byDetector
      : undefined
  if (typeof rawByDetector === `object` && rawByDetector !== null) {
    for (const [detector, counts] of Object.entries(rawByDetector)) {
      byDetector[detector] = {
        nudges: countOf(counts, `nudges`),
        escalations: countOf(counts, `escalations`),
      }
    }
  }
  return {
    loopsDetected: countOf(value, `loopsDetected`),
    nudges: countOf(value, `nudges`),
    nudgesResolved: countOf(value, `nudgesResolved`),
    escalations: countOf(value, `escalations`),
    stops: countOf(value, `stops`),
    ignores: countOf(value, `ignores`),
    byDetector,
  }
}

/** The sum of two sets of counts. */
export function addStats(base: LoopBreakerStats, delta: LoopBreakerStats): LoopBreakerStats {
  const byDetector: Record<string, { nudges: number; escalations: number }> = {
    ...base.byDetector,
  }
  for (const [detector, counts] of Object.entries(delta.byDetector)) {
    const current = byDetector[detector] ?? { nudges: 0, escalations: 0 }
    byDetector[detector] = {
      nudges: current.nudges + counts.nudges,
      escalations: current.escalations + counts.escalations,
    }
  }
  return {
    loopsDetected: base.loopsDetected + delta.loopsDetected,
    nudges: base.nudges + delta.nudges,
    nudgesResolved: base.nudgesResolved + delta.nudgesResolved,
    escalations: base.escalations + delta.escalations,
    stops: base.stops + delta.stops,
    ignores: base.ignores + delta.ignores,
    byDetector,
  }
}

/** Whether any count is above zero (nothing to flush otherwise). */
export function hasCounts(stats: LoopBreakerStats): boolean {
  return (
    stats.loopsDetected +
      stats.nudges +
      stats.nudgesResolved +
      stats.escalations +
      stats.stops +
      stats.ignores >
    0
  )
}

