/**
 * The core's entry points: what the adapter calls on each engine event.
 * Each is a pure function from the detection state (one `$.state` value) to
 * the next state plus the decisions to carry out.
 */
import { NEVER_COUNTED_TOOLS } from './constants.ts'
import type { DetectorConfig } from './config.ts'
import { DETECTORS } from './detectors/index.ts'
import { toRecord } from './fingerprint.ts'
import { tailOf } from './normalize.ts'
import {
  applyRecord,
  applySignal,
  applyTurnEnd,
  applyUserPrompt,
  ignoreSignature,
  pruneLoops,
  setPaused,
} from './policy.ts'
import type { CallRecord, Decision, DetectionState, ToolObservation } from './types.ts'
import { appendRecord, resetAllForUserPrompt, windowOf, withLoop } from './window.ts'

/** The next state and what the adapter should do about it. */
export interface PipelineStep {
  readonly state: DetectionState
  readonly decisions: readonly Decision[]
  /** The record built for the observation, when it was counted. */
  readonly record?: CallRecord
}

/** Whether one of the user's `ignoreCommands` substrings appears in the call's command or label. */
function matchesIgnoreList(
  record: CallRecord,
  observation: ToolObservation,
  config: DetectorConfig,
): boolean {
  if (config.ignoreCommands.length === 0) return false
  const command =
    typeof observation.input.command === `string` ? tailOf(observation.input.command) : ``
  const haystacks = [command.toLowerCase(), record.label.toLowerCase()]
  return config.ignoreCommands.some(entry => haystacks.some(haystack => haystack.includes(entry)))
}

/** Whether an observation stays out of detection entirely. */
function isUncounted(observation: ToolObservation): boolean {
  return (
    NEVER_COUNTED_TOOLS.has(observation.tool) ||
    observation.outcome === `interrupted` ||
    observation.outcome === `background`
  )
}

/**
 * The record for one finished tool call, or `undefined` when the call stays
 * out of detection (never-counted tools, interrupts, background launches,
 * the ignore list). Pure and independent of the state, so the adapter builds
 * it once, outside its state compare-and-swap, however often that retries.
 */
export function recordFor(
  observation: ToolObservation,
  config: DetectorConfig,
): CallRecord | undefined {
  if (isUncounted(observation)) return undefined
  const record = toRecord(observation)
  return matchesIgnoreList(record, observation, config) ? undefined : record
}

/**
 * Processes one record: append it to its loop's window, resolve the
 * signatures it breaks, run the detectors (first in precedence wins) and
 * apply the policy.
 */
export function processRecord(
  state: DetectionState,
  record: CallRecord,
  config: DetectorConfig,
): PipelineStep {
  const window = appendRecord(windowOf(state, record.loopId, record.at), record)
  const withWindow = withLoop(state, record.loopId, window)
  const livePolicy = pruneLoops(withWindow.policy, new Set(Object.keys(withWindow.loops)))
  const resolved = applyRecord(livePolicy, record)

  const signal = DETECTORS.map(detector => detector.detect(window, record, config)).find(
    found => found !== undefined,
  )
  const applied =
    signal === undefined
      ? { policy: resolved.policy, decisions: [] }
      : applySignal(resolved.policy, signal, config, record.at)

  return {
    state: { ...withWindow, policy: applied.policy },
    decisions: [...resolved.decisions, ...applied.decisions],
    record,
  }
}

/** Processes one finished tool call: `recordFor`, then `processRecord`. */
export function processObservation(
  state: DetectionState,
  observation: ToolObservation,
  config: DetectorConfig,
): PipelineStep {
  const record = recordFor(observation, config)
  return record === undefined ? { state, decisions: [] } : processRecord(state, record, config)
}

/** A prompt from the person: every loop's streaks start over. */
export function processUserPrompt(state: DetectionState, now: number): DetectionState {
  const reset = resetAllForUserPrompt(state, now)
  return { ...reset, policy: applyUserPrompt(reset.policy) }
}

/** The turn ended: the per-turn nudge budget resets. */
export function processTurnEnd(state: DetectionState): DetectionState {
  return { ...state, policy: applyTurnEnd(state.policy) }
}

/** The person pressed Ignore on a signature. */
export function processIgnore(state: DetectionState, signature: string): DetectionState {
  return { ...state, policy: ignoreSignature(state.policy, signature) }
}

/** `/loop-breaker off|on`. */
export function processPause(state: DetectionState, isPaused: boolean): DetectionState {
  return { ...state, policy: setPaused(state.policy, isPaused) }
}

