/**
 * Loop windows: the bounded, per-loop record of calls since the last user
 * prompt, plus each loop's file edit histories. Everything is plain data with
 * pure updates, so the whole detection state round-trips through `$.state`
 * (it survives hot reloads) and through JSON.
 */
import {
  DETECTION_STATE_VERSION,
  MAIN_LOOP,
  MAX_LOOPS,
  MAX_TRACKED_FILES,
  WINDOW_CAP,
} from './constants.ts'
import { emptyFileHistory, recordFileChange } from './file-tracker.ts'
import type {
  CallRecord,
  DetectionState,
  FileHistory,
  LoopId,
  LoopWindow,
  PolicyState,
} from './types.ts'

/** A loop with nothing recorded yet. */
export function emptyWindow(now: number): LoopWindow {
  return { records: [], files: {}, touchedAt: now }
}

/** A policy that remembers nothing. */
export function emptyPolicy(): PolicyState {
  return { signatures: {}, nudgesThisTurn: 0, covered: {}, ignored: [], isPaused: false }
}

/** The state a session starts with. */
export function emptyDetectionState(): DetectionState {
  return { version: DETECTION_STATE_VERSION, loops: {}, policy: emptyPolicy() }
}

/** Drops the least recently touched entries beyond `limit`. */
function keepMostRecent<T extends { readonly touchedAt: number }>(
  entries: Readonly<Record<string, T>>,
  limit: number,
): Readonly<Record<string, T>> {
  const keys = Object.keys(entries)
  if (keys.length <= limit) return entries
  const kept = Object.entries(entries)
    .sort(([, a], [, b]) => b.touchedAt - a.touchedAt)
    .slice(0, limit)
  return Object.fromEntries(kept)
}

/** Updates the edit history of the record's file, when it changed one. */
function withFileChange(
  window: LoopWindow,
  record: CallRecord,
): Readonly<Record<string, FileHistory>> {
  if (!record.isEdit || record.file === undefined) return window.files
  const history = window.files[record.file] ?? emptyFileHistory(record.at)
  const files = { ...window.files, [record.file]: recordFileChange(history, record) }
  return keepMostRecent(files, MAX_TRACKED_FILES)
}

/** Appends a record (oldest dropped past `WINDOW_CAP`) and updates file histories. */
export function appendRecord(window: LoopWindow, record: CallRecord): LoopWindow {
  const records = [...window.records, record]
  return {
    records: records.length > WINDOW_CAP ? records.slice(-WINDOW_CAP) : records,
    files: withFileChange(window, record),
    touchedAt: record.at,
  }
}

/**
 * A fresh window for a new user prompt: streaks, cycles and edit histories
 * start over (prior-art consensus: detection scope is since the last user message).
 */
export function resetForUserPrompt(_window: LoopWindow, now: number): LoopWindow {
  return emptyWindow(now)
}

/** The window of `loopId`, or an empty one. */
export function windowOf(state: DetectionState, loopId: LoopId, now: number): LoopWindow {
  return state.loops[loopId] ?? emptyWindow(now)
}

/** Whether a window holds a failure or denial: a streak that eviction would erase. */
function hasFailure(window: LoopWindow): boolean {
  return window.records.some(record => record.outcome === `error` || record.outcome === `denied`)
}

/**
 * The subagent windows to keep: those with failures first, then the most
 * recently touched. Plain least-recently-used eviction thrashes when more
 * subagents than slots take turns (a 9-way fan-out evicts each one just
 * before its next call), and a looping subagent would never build a streak.
 */
function keepSubagents(
  subagents: Readonly<Record<LoopId, LoopWindow>>,
  limit: number,
): Readonly<Record<LoopId, LoopWindow>> {
  const entries = Object.entries(subagents)
  if (entries.length <= limit) return subagents
  const kept = entries
    .sort(
      ([, a], [, b]) => Number(hasFailure(b)) - Number(hasFailure(a)) || b.touchedAt - a.touchedAt,
    )
    .slice(0, limit)
  return Object.fromEntries(kept)
}

/**
 * Stores a loop's window, evicting subagent loops beyond `MAX_LOOPS` (healthy,
 * least recently touched ones first). The main loop is never evicted: many
 * short-lived subagents must not erase the main conversation's streak.
 */
export function withLoop(
  state: DetectionState,
  loopId: LoopId,
  window: LoopWindow,
): DetectionState {
  const { [MAIN_LOOP]: main, ...subagents } = { ...state.loops, [loopId]: window }
  const keptSubagents = keepSubagents(subagents, main === undefined ? MAX_LOOPS : MAX_LOOPS - 1)
  return {
    ...state,
    loops: main === undefined ? keptSubagents : { [MAIN_LOOP]: main, ...keptSubagents },
  }
}

/** Every loop window reset for a new user prompt. */
export function resetAllForUserPrompt(state: DetectionState, now: number): DetectionState {
  const loops = Object.fromEntries(
    Object.entries(state.loops).map(([loopId, window]) => [
      loopId,
      resetForUserPrompt(window, now),
    ]),
  )
  return { ...state, loops }
}

