/**
 * The detection core's state as Loop Breaker keeps it in `$.state`: one JSON
 * string, so the observer makes a single write per tool call (spike R7), and
 * so a value written by an older build that no longer parses is replaced by
 * a fresh state instead of breaking detection (fail-safe).
 *
 * The `$.state` atoms themselves are declared in `register.tsx`: `claude
 * plugin validate` reads a state reference only from a const of that file.
 */
import { DETECTION_STATE_VERSION } from '../core/constants.ts'
import type { DetectionState } from '../core/types.ts'
import { emptyDetectionState } from '../core/window.ts'

/** Whether a value is a plain object. */
function isObject(value: unknown): value is Readonly<Record<string, unknown>> {
  return typeof value === `object` && value !== null && !Array.isArray(value)
}

/** Whether parsed JSON has the detection state's outline (written by this build). */
function isDetectionState(value: unknown): value is DetectionState {
  if (!isObject(value) || value.version !== DETECTION_STATE_VERSION || !isObject(value.loops))
    return false
  const { policy } = value
  return (
    isObject(policy) &&
    isObject(policy.signatures) &&
    isObject(policy.covered) &&
    Array.isArray(policy.ignored) &&
    typeof policy.nudgesThisTurn === `number` &&
    typeof policy.isPaused === `boolean`
  )
}

/** The detection state read back, and whether a stored value had to be thrown away. */
export interface DetectionRead {
  readonly state: DetectionState
  /** A non-empty value that did not parse or was of another version (it is logged once). */
  readonly wasDiscarded: boolean
}

/** The detection state stored as JSON, or a fresh one when it is absent or unreadable. */
export function readDetection(json: string): DetectionRead {
  if (json === ``) return { state: emptyDetectionState(), wasDiscarded: false }
  try {
    const value: unknown = JSON.parse(json)
    return isDetectionState(value)
      ? { state: value, wasDiscarded: false }
      : { state: emptyDetectionState(), wasDiscarded: true }
  } catch {
    return { state: emptyDetectionState(), wasDiscarded: true }
  }
}

/** The detection state stored as JSON (see `readDetection`). */
export function parseDetection(json: string): DetectionState {
  return readDetection(json).state
}

/** The detection state as stored. */
export function serializeDetection(state: DetectionState): string {
  return JSON.stringify(state)
}

