/**
 * Limits and lists the detection core shares. Every number here was chosen in
 * the plan (phase-2.md) from prior art; Phase 3 calibrates the thresholds in
 * `config.ts`, not these structural limits.
 */

/** The loop id of the main conversation; subagents use their `agentId`. */
export const MAIN_LOOP = `main`

/** The detection state's format version; a state of another version is replaced, not read. */
export const DETECTION_STATE_VERSION = 1

/** Calls kept per loop, since the last user prompt (OpenHands 20, OpenClaw 30). */
export const WINDOW_CAP = 30

/** Loops tracked at once; beyond this, healthy subagent loops are evicted, least recently touched first. */
export const MAX_LOOPS = 8

/** Files whose edit history is tracked per loop. */
export const MAX_TRACKED_FILES = 20

/** States remembered per tracked file. */
export const FILE_HISTORY_CAP = 20

/** Characters of tool output the core ever looks at: the tail, where errors surface. */
export const OUTPUT_TAIL_CHARS = 4096

/** Error-looking lines kept from one output when building fingerprints. */
export const MAX_ERROR_LINES = 20

/** Longest human snippet carried into state, the band and nudges. */
export const SNIPPET_CAP = 200

/** Longest action label (`npm test`, `Edit src/a.ts`). */
export const LABEL_CAP = 60

/** Characters of a generic tool input serialised into its args key. */
export const ARGS_KEY_INPUT_CAP = 2048

/** Calls back an error class must recur within to count as an environment blocker. */
export const ENV_BLOCKER_SPAN = 10

/** Model-facing nudges allowed per turn, across all loops and signatures. */
export const MAX_NUDGES_PER_TURN = 2

/** Share of a new signal's evidence already covered by an earlier nudge that suppresses it. */
export const EVIDENCE_OVERLAP_LIMIT = 0.5

/** Evidence ids remembered per loop for overlap suppression. */
export const COVERED_EVIDENCE_CAP = 60

/** Extra recurrences after escalation before an opt-in auto-stop. */
export const AUTO_STOP_DELTA = 2

/** Periods the cycle detector looks for (period 1 is a plain repeat). */
export const CYCLE_PERIODS = [2, 3, 4] as const

/** Tools that never count: planning, bookkeeping and asking the user. */
export const NEVER_COUNTED_TOOLS: ReadonlySet<string> = new Set([
  `TodoWrite`,
  `ToolSearch`,
  `AskUserQuestion`,
  `ScheduleWakeup`,
  `EnterPlanMode`,
  `ExitPlanMode`,
  `TaskCreate`,
  `TaskUpdate`,
])

/** Tools whose whole purpose is waiting on something: the poll class. */
export const POLL_TOOLS: ReadonlySet<string> = new Set([
  `Monitor`,
  `TaskGet`,
  `GetTask`,
  `TaskList`,
  `Poll`,
  `TaskOutput`,
  `BashOutput`,
])

/** Tools that change files and so count as "progress" between verification runs. */
export const EDIT_TOOLS: ReadonlySet<string> = new Set([`Edit`, `Write`, `NotebookEdit`])

/** Model-facing text is tagged with this, so the transcript says who wrote it. */
export const NUDGE_TAG = `[Loop Breaker]`

/** Segments of an absolute path kept after normalisation (`<abs>/proj/src/users.ts`; `/api/v1/users` ≠ `/api/v2/users`). */
export const ABSOLUTE_PATH_KEPT_SEGMENTS = 3

/** UTF-16 high-surrogate range: a cut must not leave one dangling. */
export const HIGH_SURROGATE_FIRST = 0xd800
export const HIGH_SURROGATE_LAST = 0xdbff

/** Longest nudge sent to the model. */
export const NUDGE_CAP = 400

/** Longest band title. */
export const TITLE_CAP = 120

/** Signatures the user ignored, remembered per session. */
export const IGNORED_CAP = 100

/** Signatures the policy remembers at once; the least recently seen go first. */
export const MAX_SIGNATURES = 200

/** User ignore entries kept, and the longest entry accepted. */
export const IGNORE_ENTRY_MAX_COUNT = 50
export const IGNORE_ENTRY_MAX_LENGTH = 200

