import type { DETECTION_STATE_VERSION } from './constants.ts'

/**
 * The detection core's vocabulary. Every type is plain JSON-serialisable data
 * so the adapter can keep the whole detection state in one `$.state` value
 * (one write per tool call, spike R7) and the core can run unchanged in Node.
 */

/** `main` for the main conversation, else the subagent's `agentId`. */
export type LoopId = string

/** How a tool call ended, as far as loop detection cares. */
export type Outcome = `ok` | `error` | `denied` | `interrupted` | `background`

/** Failure classes the model usually cannot fix by itself, plus timeouts. */
export type ErrorClass =
  | `command-not-found`
  | `permission`
  | `network`
  | `auth`
  | `rate-limit`
  | `missing-module`
  | `disk`
  | `timeout`

/** The detectors, in precedence order (see `detectors/index.ts`). */
export type DetectorId =
  | `env-blocker`
  | `denied-retry`
  | `repeat-failure`
  | `same-error`
  | `edit-thrash`
  | `cycle`
  | `idle-repeat`
  | `poll`

/**
 * One finished tool call, described without any engine type. The adapter
 * builds it from `tool.call`'s input and result (Phase 4).
 */
export interface ToolObservation {
  /** The engine's `tool_use_id`. */
  readonly id: string
  readonly loopId: LoopId
  readonly tool: string
  readonly input: Readonly<Record<string, unknown>>
  readonly outcome: Outcome
  /** What the model read: the error text on failure (starts `Exit code N` for Bash), else the output. */
  readonly text?: string
  /** Edit only: the file's content before the edit (`result.originalFile`), `null` for none. */
  readonly originalFile?: string | null
  /** The engine's own read-only verdict for this call. */
  readonly isReadOnly: boolean
  /** Milliseconds, as the adapter's clock reads them: when the result arrived. */
  readonly at: number
  /**
   * When the model issued the call. Absent means after every earlier result;
   * earlier means it was issued together with others (one message, several calls).
   */
  readonly startedAt?: number
}

/** A tool call after normalisation: everything detectors need, nothing they don't. */
export interface CallRecord {
  readonly id: string
  readonly loopId: LoopId
  readonly tool: string
  /** Tool plus key-sorted, normalised input minus cosmetic fields. */
  readonly argsKey: string
  /** Short human label: `npm test`, `Edit src/api/users.ts`. */
  readonly label: string
  readonly outcome: Outcome
  /** Exact normalised outcome (keeps `file:line:col`); for repeats, cycles, polls. */
  readonly outcomeFp: string
  /** Coarse failure identity (line numbers stripped); failures only. */
  readonly errorSig?: string
  readonly errorClass?: ErrorClass
  /** The token an environment error names, e.g. `pnpm` for `command not found: pnpm`. */
  readonly errorToken?: string
  /** Most specific error line, redacted and capped; failures only. */
  readonly snippet?: string
  /** Edit/Write: the file the call changed. */
  readonly file?: string
  /** Edit/Write that succeeded: content hash after the call, when computable. */
  readonly fileHashAfter?: string
  /** Edit/Write: content hash before the call, when known. */
  readonly fileHashBefore?: string
  /** Edit: hashes of the replaced and replacing text, for inverse-edit checks. */
  readonly editPair?: readonly [string, string]
  readonly isEdit: boolean
  readonly isReadOnly: boolean
  readonly isVerification: boolean
  readonly isPoll: boolean
  /** Bash that only moves between versions (`git checkout`, `stash`, `bisect`…). */
  readonly isNavigation: boolean
  /** A PreToolUse hook refused the call (recorded as `denied`): a procedural block, not a person's no. */
  readonly isGuardBlock: boolean
  readonly at: number
  /** See `ToolObservation.startedAt`. */
  readonly startedAt?: number
}

/** One successful content change of a file. */
export interface FileEdit {
  readonly id: string
  /** Content hash before the change, when known. */
  readonly before?: string
  /** Content hash after the change, when computable. */
  readonly after?: string
  /** Edit only: `[hash(old_string), hash(new_string)]`. */
  readonly pair?: readonly [string, string]
}

/** Edit history of one file within a loop's current scope. */
export interface FileHistory {
  /** Successful, content-changing edits in order (failed and no-op ones are skipped). */
  readonly edits: readonly FileEdit[]
  readonly touchedAt: number
}

/** One loop's detection window, since the last user prompt. */
export interface LoopWindow {
  readonly records: readonly CallRecord[]
  readonly files: Readonly<Record<string, FileHistory>>
  readonly touchedAt: number
}

/** When a nudged or escalated signature counts as resolved. */
export type ResolveWhen =
  | { readonly kind: `action-succeeds`; readonly argsKey: string }
  | {
      readonly kind: `error-changes`
      readonly errorSig: string
      readonly argsKeys: readonly string[]
    }
  | { readonly kind: `output-changes`; readonly argsKey: string; readonly outcomeFp: string }
  | { readonly kind: `user-prompt` }

/** A detector's finding: this signature has recurred `count` times. */
export interface Signal {
  readonly detector: DetectorId
  /** `detector:key`, stable across reloads; the unit of nudging, ignoring and escalating. */
  readonly signature: string
  readonly loopId: LoopId
  readonly count: number
  readonly nudgeAt: number
  readonly escalateAt: number
  /** Call ids that make up the streak. */
  readonly evidence: readonly string[]
  /** What repeated, for people: `npm test`, `Edit src/a.ts`, `pnpm`. */
  readonly label: string
  readonly snippet?: string
  readonly errorClass?: ErrorClass
  readonly errorToken?: string
  readonly resolveWhen: ResolveWhen
}

/**
 * Where a signature stands on the ladder. `watching`: reached the nudge
 * threshold but was not nudged (steering off, or the per-turn nudge budget
 * spent), so it waits for the escalation threshold. `shadowed`: its evidence
 * was already covered by another signature's nudge, so it stays silent.
 */
export type Stage = `nudged` | `watching` | `escalated` | `stopped` | `shadowed`

/** The policy's memory of one signature. */
export interface SignatureState {
  readonly signature: string
  readonly detector: DetectorId
  readonly loopId: LoopId
  readonly stage: Stage
  readonly count: number
  readonly wasNudged: boolean
  readonly resolveWhen: ResolveWhen
  readonly firstAt: number
  readonly lastAt: number
}

/** Everything the policy remembers between calls. */
export interface PolicyState {
  readonly signatures: Readonly<Record<string, SignatureState>>
  readonly nudgesThisTurn: number
  /** Per loop, evidence already covered by a nudge or escalation. */
  readonly covered: Readonly<Record<LoopId, readonly string[]>>
  readonly ignored: readonly string[]
  readonly isPaused: boolean
}

/** The whole detection state: what the adapter keeps in one `$.state` value. */
export interface DetectionState {
  readonly version: typeof DETECTION_STATE_VERSION
  readonly loops: Readonly<Record<LoopId, LoopWindow>>
  readonly policy: PolicyState
}

/** Copy for the user-facing band (Phase 5 draws it). */
export interface AlertCopy {
  readonly title: string
  readonly detail: string
  readonly hintTemplate: string
}

/** What the policy asks the adapter to do. */
export type Decision =
  | { readonly kind: `nudge`; readonly signal: Signal; readonly text: string }
  | { readonly kind: `escalate`; readonly signal: Signal; readonly alert: AlertCopy }
  | { readonly kind: `stop`; readonly signal: Signal }
  | {
      readonly kind: `resolve`
      readonly signature: string
      readonly detector: DetectorId
      readonly loopId: LoopId
      readonly wasNudged: boolean
    }

