/**
 * Turns one `tool.call` (the input the model sent and the result the engine
 * answered) into the core's engine-agnostic `ToolObservation`. No `$`; the
 * only state is a counter that keeps fallback ids unique.
 *
 * Shapes verified in the Phase 1 spikes:
 * - A failure is `isError: true`; its `result` is the stored error string,
 *   never the tool's record, and `text` starts `Exit code N` for Bash (R3).
 *   Refusals and interrupts can arrive the same way, so their texts are
 *   recognised (`refusalKindOf`), and a PreToolUse block is mapped by the core.
 * - Only when `isError` is absent is `result` the tool's record: Bash's
 *   `interrupted`, `backgroundTaskId` and `backgroundedByTurnAbort` (R2b, R3),
 *   Edit's and Write's `originalFile` (R4).
 * - `{ deny }` is a refusal from a hook beneath this one.
 * - `agentId` is set on a subagent's calls (R6).
 */
import type { ToolCallInput, ToolCallResult } from 'claude-code'

import { MAIN_LOOP } from '../core/constants.ts'
import { refusalKindOf, tailOf } from '../core/normalize.ts'
import type { Outcome, ToolObservation } from '../core/types.ts'

/** Keys of `tool.call`'s input that are the engine's, not the tool's arguments. */
const RESERVED_KEYS: ReadonlySet<string> = new Set([`tool`, `tool_use_id`, `agentId`, `consent`])

/** Calls observed without an engine id so far, to keep fallback ids unique. */
let unnamedCalls = 0

/** When a call was issued and when its result arrived, in milliseconds. */
export interface CallTimes {
  readonly startedAt: number
  readonly at: number
}

/** A plain object's fields, or `undefined`. */
function recordOf(value: unknown): Readonly<Record<string, unknown>> | undefined {
  return typeof value === `object` && value !== null && !Array.isArray(value)
    ? (value as Readonly<Record<string, unknown>>)
    : undefined
}

/** The tail of a text, capped before the core ever sees it (never the full output). */
function capped(text: unknown): string | undefined {
  return typeof text === `string` ? tailOf(text) : undefined
}

/** The tool's own arguments: the input minus the engine's reserved keys. */
function argumentsOf(e: ToolCallInput): Readonly<Record<string, unknown>> {
  return Object.fromEntries(
    Object.entries(e as unknown as Readonly<Record<string, unknown>>).filter(
      ([key]) => !RESERVED_KEYS.has(key),
    ),
  )
}

/** How the call ended, and the text that goes with it. */
function outcomeOf(ran: ToolCallResult): { readonly outcome: Outcome; readonly text?: string } {
  if (typeof ran.deny === `string`) return { outcome: `denied`, text: capped(ran.deny) ?? `` }
  const text = capped(ran.text)
  if (ran.isError === true) {
    // The whole text: a refusal leads it, and a person's feedback after it can be long (review C1).
    const refusal = refusalKindOf(typeof ran.text === `string` ? ran.text : ``)
    return text === undefined
      ? { outcome: refusal ?? `error` }
      : { outcome: refusal ?? `error`, text }
  }
  const record = recordOf(ran.result)
  if (record?.interrupted === true) return { outcome: `interrupted` }
  if (typeof record?.backgroundTaskId === `string` || record?.backgroundedByTurnAbort === true) {
    return { outcome: `background` }
  }
  return text === undefined ? { outcome: `ok` } : { outcome: `ok`, text }
}

/** Edit/Write: the file's content before the call, as the engine recorded it (R4). */
function originalFileOf(ran: ToolCallResult): string | null | undefined {
  if (ran.isError === true || typeof ran.deny === `string`) return undefined
  const original = recordOf(ran.result)?.originalFile
  return typeof original === `string` || original === null ? original : undefined
}

/** An id for a call the engine gave none: unique, even for calls issued together. */
function unnamedId(tool: string, startedAt: number): string {
  unnamedCalls += 1
  return `${tool}@${String(startedAt)}#${String(unnamedCalls)}`
}

/** The core's view of one finished tool call. */
export function observationOf(
  e: ToolCallInput,
  ran: ToolCallResult,
  times: CallTimes,
): ToolObservation {
  const { outcome, text } = outcomeOf(ran)
  const originalFile = originalFileOf(ran)
  return {
    id: typeof e.tool_use_id === `string` ? e.tool_use_id : unnamedId(e.tool, times.startedAt),
    loopId: e.agentId ?? MAIN_LOOP,
    tool: e.tool,
    input: argumentsOf(e),
    outcome,
    ...(text === undefined ? {} : { text }),
    ...(originalFile === undefined ? {} : { originalFile }),
    isReadOnly: ran.isReadOnly === true,
    at: times.at,
    startedAt: times.startedAt,
  }
}

