/**
 * Turns the core's decisions for one call into what the adapter records: the
 * alert, the timeline and the counts. (The notes for the model are attached
 * first, straight from the decisions: see `observer.ts`.)
 * Pure: the observer carries the plan out through the engine port (`ports.ts`).
 */
import type {
  LoopBreakerAlert,
  LoopBreakerStats,
  LoopBreakerTimelineEntry,
} from '../../types/index.d.ts'
import type { Decision, DetectorId } from '../core/types.ts'
import { emptyStats } from './stats.ts'

/** What to do about one call's decisions. */
export interface EffectsPlan {
  /** The newest escalation, for the band and the toast; its `agentName` is filled in later. */
  readonly escalation?: LoopBreakerAlert
  /** Signatures whose loop is over: an alert about one of them is taken down. */
  readonly resolved: readonly string[]
  readonly timeline: readonly LoopBreakerTimelineEntry[]
  /** Counts to add to the session's pending stats. */
  readonly stats: LoopBreakerStats
}

/** Counts with one detector's nudge or escalation added. */
function countDetector(
  stats: LoopBreakerStats,
  detector: DetectorId,
  field: `nudges` | `escalations`,
): LoopBreakerStats {
  const current = stats.byDetector[detector] ?? { nudges: 0, escalations: 0 }
  return {
    ...stats,
    byDetector: { ...stats.byDetector, [detector]: { ...current, [field]: current[field] + 1 } },
  }
}

/**
 * The plan for one call's decisions.
 *
 * @param decisions what the core decided, in order
 * @param now when, in milliseconds
 * @param alerted signatures that already alerted this session (a loop is
 *   counted once, at its first nudge or escalation)
 */
export function planFor(
  decisions: readonly Decision[],
  now: number,
  alerted: ReadonlySet<string>,
): EffectsPlan {
  const resolved: string[] = []
  const timeline: LoopBreakerTimelineEntry[] = []
  const seen = new Set(alerted)
  let stats = emptyStats()
  let escalation: LoopBreakerAlert | undefined

  for (const decision of decisions) {
    if (decision.kind === `resolve`) {
      resolved.push(decision.signature)
      timeline.push({
        at: now,
        signature: decision.signature,
        detector: decision.detector,
        decision: `resolve`,
        label: decision.detector,
        loopId: decision.loopId,
      })
      if (decision.wasNudged) stats = { ...stats, nudgesResolved: stats.nudgesResolved + 1 }
      continue
    }
    const { signal } = decision
    timeline.push({
      at: now,
      signature: signal.signature,
      detector: signal.detector,
      decision: decision.kind,
      label: signal.label,
      loopId: signal.loopId,
    })
    if (decision.kind !== `stop` && !seen.has(signal.signature)) {
      seen.add(signal.signature)
      stats = { ...stats, loopsDetected: stats.loopsDetected + 1 }
    }
    switch (decision.kind) {
      case `nudge`:
        stats = countDetector({ ...stats, nudges: stats.nudges + 1 }, signal.detector, `nudges`)
        break
      case `escalate`:
        escalation = {
          signature: signal.signature,
          detector: signal.detector,
          loopId: signal.loopId,
          agentName: null,
          title: decision.alert.title,
          detail: decision.alert.detail,
          hintTemplate: decision.alert.hintTemplate,
          count: signal.count,
          since: now,
        }
        stats = countDetector(
          { ...stats, escalations: stats.escalations + 1 },
          signal.detector,
          `escalations`,
        )
        break
      case `stop`:
        stats = { ...stats, stops: stats.stops + 1 }
        break
    }
  }

  return {
    ...(escalation === undefined ? {} : { escalation }),
    resolved,
    timeline,
    stats,
  }
}

