/**
 * Loop Breaker's state contract: every value it keeps in `$.state`, declared
 * for `claude plugin validate` and the editor. Self-contained by design (the
 * engine reads it alone), so the core's own types are not imported here.
 */

/** A loop the person is being told about: what the band above the prompt draws. */
export type LoopBreakerAlert = {
  signature: string
  detector: string
  loopId: string
  /** The subagent's name or type when the loop runs in one; `null` on the main loop. */
  agentName: string | null
  title: string
  detail: string
  hintTemplate: string
  count: number
  /** When it escalated, in milliseconds. */
  since: number
}

/** One decision, for the session's timeline (`/loop-breaker`). */
export type LoopBreakerTimelineEntry = {
  at: number
  signature: string
  detector: string
  decision: 'nudge' | 'escalate' | 'stop' | 'resolve' | 'ignore'
  label: string
  loopId: string
}

/** Counts only: how often Loop Breaker acted, and how often a nudge worked. Never content. */
export type LoopBreakerStats = {
  loopsDetected: number
  nudges: number
  nudgesResolved: number
  escalations: number
  stops: number
  ignores: number
  byDetector: Record<string, { nudges: number; escalations: number }>
}

declare module 'claude-code' {
  interface PluginState {
    'loop-breaker': {
      /** The detection core's state as JSON (windows and policy): one write per tool call. */
      detection: string
      alert: LoopBreakerAlert | null
      /** The newest decisions, capped at 100. */
      timeline: LoopBreakerTimelineEntry[]
      /** The main loop's running turn, for Stop. */
      mainTurnId: string | null
      /** Counts not yet added to the store (flushed when a turn completes). */
      pendingStats: LoopBreakerStats
    }
  }
}

