/**
 * Sensitivity presets and user-option resolution.
 *
 * `balanced` carries the prior-art consensus (nudge at 3, escalate at 5; see
 * phase-2.md). `relaxed` waits one more recurrence to nudge and two more to
 * escalate; `strict` acts one sooner, never below 2. Phase 3 calibrates these
 * against the evaluation corpus and records the result in `tuning.md`.
 */
import { IGNORE_ENTRY_MAX_COUNT, IGNORE_ENTRY_MAX_LENGTH } from './constants.ts'

/** When a signature is nudged and when it is escalated. */
export interface Ladder {
  readonly nudge: number
  readonly escalate: number
}

/** One ladder per detector. `envBlocker` nudges and escalates together. */
export interface Thresholds {
  readonly repeatFailure: Ladder
  readonly sameError: Ladder
  readonly sameErrorVerification: Ladder
  readonly cycle: Ladder
  readonly editThrash: Ladder
  readonly deniedRetry: Ladder
  readonly envBlocker: number
  readonly idleRepeat: Ladder
  readonly poll: Ladder
}

export type Sensitivity = `relaxed` | `balanced` | `strict`

/** The resolved configuration every core function reads. */
export interface DetectorConfig {
  readonly sensitivity: Sensitivity
  readonly thresholds: Thresholds
  /** Send model-facing nudges; when off, signatures go straight to escalation. */
  readonly steer: boolean
  /** Stop the turn when a loop continues after escalation (opt-in). */
  readonly autoStop: boolean
  /**
   * Lower-case substrings: a call whose command or label contains one is never
   * counted. Plain substrings, not regexes: a user regex like `(a+)+$` could
   * freeze the hooks worker (Phase 2 review).
   */
  readonly ignoreCommands: readonly string[]
}

/** No threshold goes below this: a single occurrence is never a loop. */
export const MIN_THRESHOLD = 2
const RELAXED_NUDGE_DELTA = 1
const RELAXED_ESCALATE_DELTA = 2
const STRICT_DELTA = -1

const BALANCED: Thresholds = {
  repeatFailure: { nudge: 3, escalate: 5 },
  sameError: { nudge: 3, escalate: 5 },
  sameErrorVerification: { nudge: 4, escalate: 6 },
  cycle: { nudge: 3, escalate: 5 },
  editThrash: { nudge: 3, escalate: 5 },
  deniedRetry: { nudge: 2, escalate: 3 },
  envBlocker: 3,
  idleRepeat: { nudge: 5, escalate: 10 },
  poll: { nudge: 10, escalate: 20 },
}

/** Shifts a ladder, keeping `nudge ≥ MIN_THRESHOLD` and `escalate > nudge`. */
export function shiftLadder(ladder: Ladder, nudgeDelta: number, escalateDelta: number): Ladder {
  const nudge = Math.max(MIN_THRESHOLD, ladder.nudge + nudgeDelta)
  const escalate = Math.max(nudge + 1, ladder.escalate + escalateDelta)
  return { nudge, escalate }
}

/** Applies one pair of deltas to every ladder of a preset. */
function shiftAll(base: Thresholds, nudgeDelta: number, escalateDelta: number): Thresholds {
  return {
    repeatFailure: shiftLadder(base.repeatFailure, nudgeDelta, escalateDelta),
    sameError: shiftLadder(base.sameError, nudgeDelta, escalateDelta),
    sameErrorVerification: shiftLadder(base.sameErrorVerification, nudgeDelta, escalateDelta),
    cycle: shiftLadder(base.cycle, nudgeDelta, escalateDelta),
    editThrash: shiftLadder(base.editThrash, nudgeDelta, escalateDelta),
    deniedRetry: shiftLadder(base.deniedRetry, nudgeDelta, escalateDelta),
    envBlocker: Math.max(MIN_THRESHOLD, base.envBlocker + nudgeDelta),
    idleRepeat: shiftLadder(base.idleRepeat, nudgeDelta, escalateDelta),
    poll: shiftLadder(base.poll, nudgeDelta, escalateDelta),
  }
}

/** The three presets users pick from in `/config`. */
export const PRESETS: Readonly<Record<Sensitivity, Thresholds>> = {
  relaxed: shiftAll(BALANCED, RELAXED_NUDGE_DELTA, RELAXED_ESCALATE_DELTA),
  balanced: BALANCED,
  strict: shiftAll(BALANCED, STRICT_DELTA, STRICT_DELTA),
}

/** Whether `value` names a preset. */
function isSensitivity(value: unknown): value is Sensitivity {
  return value === `relaxed` || value === `balanced` || value === `strict`
}

/**
 * Parses the user's comma-separated ignore list into lower-case substrings.
 * Empty and overlong entries are dropped and reported, never thrown, so a
 * typo in `/config` cannot stop the mod from loading.
 *
 * @returns the accepted substrings and the rejected entries
 */
export function parseIgnoreList(raw: unknown): {
  readonly entries: readonly string[]
  readonly rejected: readonly string[]
} {
  if (typeof raw !== `string`) return { entries: [], rejected: [] }
  const entries: string[] = []
  const rejected: string[] = []
  const sources = raw
    .split(`,`)
    .map(source => source.trim())
    .filter(source => source !== ``)
  for (const source of sources.slice(0, IGNORE_ENTRY_MAX_COUNT)) {
    if (source.length > IGNORE_ENTRY_MAX_LENGTH) rejected.push(source)
    else entries.push(source.toLowerCase())
  }
  return { entries, rejected }
}

/**
 * Resolves the plugin's `userConfig` values (as `register(on, options)`
 * receives them) into a configuration. Unknown or malformed values fall back
 * to the defaults: balanced, steering on, auto-stop off, nothing ignored.
 */
export function resolveConfig(options: Readonly<Record<string, unknown>> = {}): DetectorConfig {
  const sensitivity = isSensitivity(options.sensitivity) ? options.sensitivity : `balanced`
  return {
    sensitivity,
    thresholds: PRESETS[sensitivity],
    steer: typeof options.steer === `boolean` ? options.steer : true,
    autoStop: typeof options.autoStop === `boolean` ? options.autoStop : false,
    ignoreCommands: parseIgnoreList(options.ignoreCommands).entries,
  }
}

