/**
 * Turns an engine-agnostic `ToolObservation` into a `CallRecord`: the args
 * key, a human label, the outcome fingerprint, and for failures the coarse
 * error signature, class and snippet.
 */
import { ARGS_KEY_INPUT_CAP, EDIT_TOOLS, LABEL_CAP, POLL_TOOLS, SNIPPET_CAP } from './constants.ts'
import { applyEdit } from './file-tracker.ts'
import { hashText } from './hash.ts'
import {
  errorDigest,
  isGitNavigationCommand,
  isGuardBlock,
  isPollCommand,
  isVerificationCommand,
  normalizeCommand,
  normalizeOutput,
  redactSecrets,
  truncate,
} from './normalize.ts'
import type { CallRecord, ToolObservation } from './types.ts'

/** Input fields that never change what an action does (Cline drops `task_progress`, OpenClaw `title`). */
const COSMETIC_FIELDS: ReadonlySet<string> = new Set([
  `description`,
  `timeout`,
  `title`,
  `task_progress`,
])
const PATH_TAIL_SEGMENTS = 2

/** Whether a value is a plain object usable as a tool input. */
function isRecord(value: unknown): value is Readonly<Record<string, unknown>> {
  return typeof value === `object` && value !== null && !Array.isArray(value)
}

/** A string field of a tool input, or `` when absent or not a string. */
function stringField(input: Readonly<Record<string, unknown>>, key: string): string {
  const value = input[key]
  return typeof value === `string` ? value : ``
}

/** A numeric field of a tool input as text, or `` when absent or not a number. */
function numberField(input: Readonly<Record<string, unknown>>, key: string): string {
  const value = input[key]
  return typeof value === `number` ? String(value) : ``
}

/** JSON with object keys sorted at every depth, so key order never changes a key. */
function stableJson(value: unknown): string {
  try {
    return JSON.stringify(value, (_key, nested: unknown) =>
      typeof nested === `object` && nested !== null && !Array.isArray(nested)
        ? Object.fromEntries(
            Object.entries(nested as Record<string, unknown>).sort(([a], [b]) =>
              a < b ? -1 : a > b ? 1 : 0,
            ),
          )
        : nested,
    )
  } catch {
    // Cyclic or otherwise unserialisable input: fall back to its key list.
    return typeof value === `object` && value !== null
      ? Object.keys(value).sort().join(`,`)
      : String(value)
  }
}

/** The last segments of a path, enough to recognise a file in a label. */
function shortPath(path: string): string {
  return path.split(`/`).filter(Boolean).slice(-PATH_TAIL_SEGMENTS).join(`/`)
}

/**
 * Identifies an action independently of cosmetic fields and key order, so the
 * same call made twice produces the same key.
 */
export function argsKey(tool: string, input: Readonly<Record<string, unknown>>): string {
  const filePath = stringField(input, `file_path`)
  switch (tool) {
    case `Bash`:
      return hashText(`Bash|${normalizeCommand(stringField(input, `command`))}`)
    case `Edit`:
      return hashText(
        `Edit|${filePath}|${hashText(stringField(input, `old_string`))}|${hashText(stringField(input, `new_string`))}|${String(input.replace_all === true)}`,
      )
    case `Write`:
      return hashText(`Write|${filePath}|${hashText(stringField(input, `content`))}`)
    case `Read`:
      return hashText(
        `Read|${filePath}|${numberField(input, `offset`)}|${numberField(input, `limit`)}`,
      )
    default: {
      const meaningful = Object.fromEntries(
        Object.entries(input).filter(([key]) => !COSMETIC_FIELDS.has(key)),
      )
      return hashText(`${tool}|${stableJson(meaningful).slice(0, ARGS_KEY_INPUT_CAP)}`)
    }
  }
}

/** A short human label for an action: `npm test`, `Edit api/users.ts`. */
export function actionLabel(tool: string, input: Readonly<Record<string, unknown>>): string {
  // Labels are shown in the band and kept in session state, so secrets in a
  // command (`PGPASSWORD=… psql`) are redacted first, then the label is cut:
  // cutting first could shorten a token below the length its pattern needs.
  const command = stringField(input, `command`)
  if (tool === `Bash` && command !== ``) {
    return truncate(redactSecrets(normalizeCommand(command)), LABEL_CAP)
  }
  const path = stringField(input, `file_path`) || stringField(input, `notebook_path`)
  if (path !== ``) return truncate(`${tool} ${shortPath(path)}`, LABEL_CAP)
  const pattern = stringField(input, `pattern`) || stringField(input, `query`)
  return truncate(redactSecrets(pattern === `` ? tool : `${tool} ${pattern}`), LABEL_CAP)
}

/** File-change facts of an Edit or Write, from its input and the engine's `originalFile`. */
function fileFacts(observation: ToolObservation): Partial<CallRecord> {
  const { tool, input, originalFile, outcome } = observation
  if (!EDIT_TOOLS.has(tool)) return {}
  const file = stringField(input, `file_path`) || stringField(input, `notebook_path`)
  if (file === ``) return {}
  const before = typeof originalFile === `string` ? { fileHashBefore: hashText(originalFile) } : {}
  if (tool === `Write`) {
    const after = outcome === `ok` ? { fileHashAfter: hashText(stringField(input, `content`)) } : {}
    return { file, ...before, ...after }
  }
  if (tool === `Edit`) {
    const oldString = stringField(input, `old_string`)
    const newString = stringField(input, `new_string`)
    const editPair = [hashText(oldString), hashText(newString)] as const
    const afterContent =
      outcome === `ok` && typeof originalFile === `string`
        ? applyEdit(originalFile, oldString, newString, input.replace_all === true)
        : undefined
    const after = afterContent === undefined ? {} : { fileHashAfter: hashText(afterContent) }
    return { file, ...before, ...after, editPair }
  }
  return { file }
}

/** Outcome fingerprint and, for failures, the error facts. */
function outcomeFacts(
  observation: ToolObservation,
): Partial<CallRecord> & { readonly outcomeFp: string } {
  const text = typeof observation.text === `string` ? observation.text : ``
  switch (observation.outcome) {
    case `error`: {
      const digest = errorDigest(text)
      const { errorClass, token } = digest.classification
      return {
        outcomeFp: hashText(`error|${digest.outcomeInput}`),
        // No real error lines → no signature, so generic failures never look alike.
        ...(digest.signatureInput === undefined
          ? {}
          : { errorSig: hashText(digest.signatureInput) }),
        snippet: digest.snippet,
        ...(errorClass === undefined ? {} : { errorClass }),
        ...(token === undefined ? {} : { errorToken: token }),
      }
    }
    case `ok`:
      return { outcomeFp: hashText(`ok|${normalizeOutput(text)}`) }
    case `denied`: {
      // A guard's reason (`PreToolUse:Edit hook error: editing .env is blocked`)
      // identifies the refusal across different attempts; a person's plain
      // "doesn't want to proceed" has no error lines and so no signature.
      const { signatureInput } = errorDigest(text)
      return {
        outcomeFp: hashText(`denied`),
        ...(signatureInput === undefined ? {} : { errorSig: hashText(signatureInput) }),
        snippet: truncate(redactSecrets(normalizeOutput(text)), SNIPPET_CAP),
      }
    }
    default:
      return { outcomeFp: hashText(observation.outcome) }
  }
}

/**
 * Normalises one observation into the record detectors read. A failure that
 * is a PreToolUse hook's block counts as a denial: the action never ran.
 */
export function toRecord(raw: ToolObservation): CallRecord {
  // The adapter builds observations from engine values; guard the shapes anyway (fail-safe).
  const isBlocked =
    raw.outcome === `error` && typeof raw.text === `string` && isGuardBlock(raw.text)
  const observation: ToolObservation = {
    ...raw,
    input: isRecord(raw.input) ? raw.input : {},
    outcome: isBlocked ? `denied` : raw.outcome,
  }
  const { id, loopId, tool, input, outcome, isReadOnly, at, startedAt } = observation
  const command = tool === `Bash` ? stringField(input, `command`) : ``
  const facts = fileFacts(observation)
  return {
    id,
    loopId,
    tool,
    argsKey: argsKey(tool, input),
    label: actionLabel(tool, input),
    outcome,
    ...outcomeFacts(observation),
    ...facts,
    isEdit: EDIT_TOOLS.has(tool),
    isReadOnly,
    isVerification: command !== `` && isVerificationCommand(command),
    isPoll: POLL_TOOLS.has(tool) || (command !== `` && isPollCommand(command)),
    isNavigation: command !== `` && isGitNavigationCommand(command),
    isGuardBlock: isBlocked,
    at,
    ...(typeof startedAt === `number` ? { startedAt } : {}),
  }
}

files.hooks/core/normalize.ts:
/**
 * Text normalisation: turns volatile tool output into stable fingerprint
 * inputs, classifies environmental errors, and recognises verification and
 * polling commands.
 *
 * Precision rules (from the Phase 2 review):
 * - Volatile values are replaced only in their own context: durations next to
 *   timing words or in parentheses, hex only when it looks like an address,
 *   absolute paths only when they really are absolute (keeping their last two
 *   segments). A duration parser's `5m` vs `1h`, or `packages/api` vs
 *   `packages/web`, must stay different.
 * - Error classes are read from real error lines only, never from test
 *   titles, passing-test lines or assertion values. A test named "rejects
 *   unauthorized requests" is not an auth failure.
 * - A failure with no real error lines gets no error signature, so empty or
 *   generic failures (`test -f x`, guessed paths) never look like "the same error".
 *
 * Regex safety is a hard rule (phase-2.md, Task 2.2). Every pattern is
 * linear-time: no nested or overlapping quantifiers, bounded `{0,200}` spans
 * instead of `.*`, and lookbehinds so a match can only start at the
 * beginning of a run. Inputs are capped to their last `OUTPUT_TAIL_CHARS`. A
 * catastrophic backtrack would block the hooks worker, and the engine unloads
 * a mod that does. `CORE_PATTERNS` lists every pattern for the adversarial test.
 */
import {
  ABSOLUTE_PATH_KEPT_SEGMENTS,
  HIGH_SURROGATE_FIRST,
  HIGH_SURROGATE_LAST,
  MAX_ERROR_LINES,
  OUTPUT_TAIL_CHARS,
  SNIPPET_CAP,
} from './constants.ts'
import type { ErrorClass } from './types.ts'

// ── Terminal noise ────────────────────────────────────────────────────────────
const ANSI_CSI = /\u001b\[[0-9;?]*[ -/]*[@-~]/g
const ANSI_OSC = /\u001b\][^\u0007\u001b]*(?:\u0007|\u001b\\)/g
const ANSI_SHORT = /\u001b[78=>()B]/g
const CONTROL_CHARS = /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g

// ── Volatile values, each only in its own context ─────────────────────────────
// `_` separators too: npm's log path (`_logs/2026-10-07T10_11_12_345Z-debug-0.log`) changes every run.
const ISO_TIMESTAMP =
  /\b\d{4}-\d{2}-\d{2}[T ]\d{2}[:_]\d{2}[:_]\d{2}(?:[.,_]\d+)?(?:Z|[+-]\d{2}:?\d{2})?/gi
const CLOCK_TIME = /\b\d{1,2}:\d{2}:\d{2}(?:[.,]\d+)?\b/g
const DURATION_UNIT = `(?:ns|µs|us|ms|s|secs?|seconds?|m|mins?|minutes?|h|hrs?|hours?)`
const TIMING_PAREN = new RegExp(
  `\\(\\s*\\d+(?:\\.\\d+)?\\s?${DURATION_UNIT}(?:\\s+\\d+(?:\\.\\d+)?\\s?${DURATION_UNIT})?\\s*\\)`,
  `gi`,
)
const TIMING_WORD = new RegExp(
  `\\b(time|took|in|after|elapsed|duration|finished in|completed in)(\\s*(?::\\s*)?)\\d+(?:\\.\\d+)?\\s?${DURATION_UNIT}\\b`,
  `gi`,
)
// A list of phase timings in parentheses: vitest's `(transform 30ms, setup 0ms, collect 50ms, …)`.
const TIMING_LIST =
  /\((?:[A-Za-z]{1,20} \d+(?:\.\d+)?(?:ms|s), ){1,12}[A-Za-z]{1,20} \d+(?:\.\d+)?(?:ms|s)\)/g
// A compound duration (`1m23s`, `2h5m`), as `gh run view` prints job times.
const COMPOUND_DURATION = /\b\d+h\d+m(?:\d+s)?\b|\b\d+m\d+s\b/g
// A relative time (`about 3 minutes ago`, `5m ago`): `gh run view` prints one that changes every run.
const RELATIVE_TIME =
  /\b(?:(?:about|almost|over|less than) )?(?:an?|\d+) ?(?:s|m|h|d|w|seconds?|minutes?|hours?|days?|weeks?|months?|years?) ago\b/gi
// A trailing `12ms` on a test-result line (vitest/jest print it there); elsewhere `ms` may be data.
const TRAILING_MILLIS = /\s\d+(?:\.\d+)?\s?ms$/
const GIT_NAVIGATION = /\bgit\s+(?:checkout|switch|stash|bisect|reset|restore)\b/
const ATTEMPT_COUNTER = /\b(attempt|retry|try)\b[\s#:=]*\d+/gi
const PROCESS_ID = /\b(pid|ppid|process)\b[\s#:=]*\d+/gi
const RANDOM_SEED = /\b(seed)\b[\s#:=]*\d+/gi
const UUID = /\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b/gi
const MEMORY_ADDRESS = /\b0x[0-9a-f]{8,}\b/gi
const OBJECT_ID = /@[0-9a-f]{6,8}\b/g
const LONG_HEX = /\b[0-9a-f]{12,}\b/gi
const TEMP_PATH = /(?:\/private)?\/(?:tmp|var\/folders)\/[^\s'"`:)\]]*/g
const LOCAL_PORT = /(localhost|127\.0\.0\.1|0\.0\.0\.0|\[::1\]):\d{2,5}/g
// Only a path that starts the token is absolute: not `packages/api/x`, not a URL's path.
const ABSOLUTE_PATH = /(?<![\w.:/~-])\/[\w.@+-]+(?:\/[\w.@+-]+)+/g
const SPACE_RUN = /[ \t]+/g

// ── Coarse error signature only ───────────────────────────────────────────────
const LINE_COLUMN = /:\d+(?::\d+)?\b/g
const LINE_WORD = /\b(line|ln|col|column)\s+\d+/gi
const RUN_COUNTER =
  /\b\d+\s+(passed|failed|skipped|pending|todo|total|tests?|suites?|errors?|warnings?)\b/gi

// ── Failure text structure ───────────────────────────────────────────────────
const EXIT_CODE_PREFIX = /^Exit code (\d+)\r?\n?/
const EXPECTED_LINE = /\b(?:expected|actual)\b\s*[:=]/i
const RECEIVED_LINE = /\b(?:received|got|but was)\b/i
const SNIPPET_JOINER = ` · `
// Assertion lines (`Expected: 201`, `Received: 500`) count as error lines, so
// failures that differ only in the asserted values keep different signatures.
const ERROR_LINE =
  /error|fail|exception|✗|×|✕|not ok|panic|traceback|denied|refused|not found|cannot|unable|expected|received|assert|●/i
// Environment keywords that may sit on a line ERROR_LINE misses (`Command timed out after 1s`).
const ENVIRONMENT_HINT_LINE =
  /timed out|connection refused|no space left|\bE(?:CONN\w+|NOTFOUND|AI_AGAIN|ACCES|PERM|NOSPC|TIMEDOUT)\b|rate[ -]?limit|too many requests|could not resolve|unreachable|getaddrinfo|\bHTTP\/\d|\bstatus(?: code)?:? \d{3}\b|unauthori[sz]ed|forbidden|invalid api key/i
// Test titles and result lines name tests; their words never classify a failure.
const TEST_TITLE_LINE =
  /^(?:[✓✔√○◯✕✗×●›❯↓]|(?:PASS|FAIL|FAILED|ok|not ok)\b|\d+\)\s|---\s?(?:FAIL|PASS)\b|\[(?:PASS|FAIL)\])/
// Snippet candidates, most specific first: the assertion, then a named error, then a FAIL line.
// `(?<!\w)` makes `\w*Error` start only at a word start, keeping it linear.
const SNIPPET_RANKING: readonly RegExp[] = [
  /\b(?:expected|actual)\b\s*[:=]/i,
  /assert|expected|received/i,
  /(?<!\w)\w*Error\b|error\[|\bE\d{3,}\b|\bTS\d{4}\b/,
  /not found|denied|refused|\bFAIL\b/i,
]

// Refusals that arrive as error text (Phase 3 review, I4): the person rejecting the call, a
// permission rule, auto mode's classifier. "Doesn't want to take this action" is the
// interrupt text (spike R2b), not a refusal.
// Each is anchored at the start of the result: a tool's own output that merely
// quotes one of these phrases (a test asserting "The tool use was rejected.")
// is a failure, not a refusal (Phase 4 review, C1).
const REFUSAL_TEXTS: readonly RegExp[] = [
  /^\s*The user doesn't want to proceed with this tool use\b/,
  /^\s*Permission to use \S{1,100} /,
  /^\s*Permission for this action was denied by the Claude Code auto mode classifier\b/,
]
const INTERRUPT_TEXT =
  /^\s*(?:\[Request interrupted by user|The user doesn't want to take this action\b)/
// A PreToolUse hook refusing the call (`PreToolUse:Edit hook error: …`): a guard's denial, not a code error.
const GUARD_BLOCK = /^PreToolUse:[\w.:-]{1,80} hook (?:error|returned blocking error|blocked)\b/

// ── Commands ──────────────────────────────────────────────────────────────────
// `(?<!\s)` lets a match start only at the first space of a run (linear on long runs).
const TRAILING_LIMITER = /(?<!\s)\s*(?:2>&1\s*)?\|\s*(?:head|tail)(?:\s+-n)?\s+-?\d+\s*$/
const TRAILING_STDERR_MERGE = /(?<!\s)\s+2>&1\s*$/
const LEADING_CD = /^cd\s+[^\s&;|]+\s*&&\s*/
const VERIFICATION_COMMAND =
  /\b(?:npm|pnpm|yarn|bun)\s+(?:run\s+)?(?:test|build|lint|typecheck|type-check|check)\b|\b(?:jest|vitest|mocha|tsc|eslint|pytest|ruff|mypy|phpunit|rspec)\b|\bgo\s+(?:test|build|vet)\b|\bcargo\s+(?:test|build|check|clippy)\b|\b(?:mvn|mvnw|gradle|gradlew)\b[^\n]{0,200}\b(?:test|build|verify|check)\b|\bdotnet\s+(?:test|build)\b|(?:^|&&\s*|;\s*)make(?:\s|$)/i
const POLL_COMMAND =
  /^\s*sleep\s+\d|(?:^|&&\s*|;\s*)watch\s|\bgh\s+run\s+(?:watch|view|list)\b|\bgh\s+pr\s+(?:checks|view|status)\b|\bkubectl\s+get\b|\bkubectl\b[^\n]{0,200}\s(?:-w|--watch)\b|\bdocker\s+(?:ps|compose\s+ps)\b|\btail\s+-f\b|\bdocker\s+logs\s+-f\b|\bcurl\b[^\n]{0,200}\b(?:health|healthz|ready|readyz|status|ping)\b/i

// ── Environmental error classes (first match wins) ──────────────────────────
interface ClassRule {
  readonly errorClass: ErrorClass
  readonly pattern: RegExp
}

const CLASS_RULES: readonly ClassRule[] = [
  {
    errorClass: `command-not-found`,
    pattern:
      /command not found:\s*([\w./-]+)|(?<![\w./-])([\w./-]+): command not found(?!:)|'([\w./-]+)' is not recognized as an internal|\bsh: \d+: ([\w./-]+): not found/i,
  },
  {
    // The shell/OS form (`open 'x': Permission denied`, `EACCES`), not prose that mentions it.
    errorClass: `permission`,
    pattern: /\bEACCES\b|\bEPERM\b|operation not permitted|:\s*permission denied\b/i,
  },
  {
    // Packages only: relative or aliased paths (`./generated/x`, `@/x`) are code errors.
    errorClass: `missing-module`,
    pattern:
      /cannot find module '(?!\.{0,2}\/|@\/|~\/)([^'\n]{1,200})'|no module named '?([\w.]+)|can't resolve '(?!\.{0,2}\/|@\/|~\/)([^'\n]{1,200})'|cannot find package '([^'\n]{1,200})'/i,
  },
  {
    // Status codes only in HTTP context, so a test asserting "got 401" is not an auth error.
    errorClass: `auth`,
    pattern:
      /\bHTTP\/\d(?:\.\d)? (?:401|403)\b|\bstatus(?: code)?:? (?:401|403)\b|\b(?:401|403) (?:Unauthorized|Forbidden)\b|invalid api key|authentication failed|requested URL returned error: (?:401|403)\b/i,
  },
  {
    errorClass: `rate-limit`,
    pattern:
      // Prose only: a file named `rate-limit.ts` is not a rate limit.
      /\b429 Too Many Requests\b|\bstatus(?: code)?:? 429\b|\brate limit (?:exceeded|reached|hit)\b|\brate[- ]limited\b|too many requests/i,
  },
  {
    errorClass: `network`,
    pattern:
      /\bECONNREFUSED\b|\bENOTFOUND\b|\bEAI_AGAIN\b|\bECONNRESET\b|connection refused|getaddrinfo|network is unreachable|could not resolve host|can't reach database server|could not connect to server/i,
  },
  { errorClass: `disk`, pattern: /\bENOSPC\b|no space left on device|disk quota exceeded/i },
  {
    errorClass: `timeout`,
    // The tool's own timeout, not a test runner's (`panic: test timed out` is a code bug).
    pattern: /command timed out after|^exit code 143\b|\bETIMEDOUT\b/im,
  },
]

// ── Secret redaction (snippets only ever leave the core redacted) ──────────
interface Redaction {
  readonly pattern: RegExp
  readonly replacement: string
}

const REDACTED = `<redacted>`
// `(?<![A-Za-z0-9_-])` starts a token only at its beginning, keeping repeated prefixes linear.
// Secret shapes, most specific first (security review, Phase 3). Bounded `{0,N}`
// spans and lookbehinds keep each pattern linear on the 4 KB tails it sees.
const SECRET_NAME = `[A-Za-z0-9_]{0,40}(?:password|passwd|pwd|secret|token|api[_-]?key|access[_-]?key|account[_-]?key|private[_-]?key|client[_-]?secret|authorization|credentials?)[A-Za-z0-9_]{0,40}`
const REDACTIONS: readonly Redaction[] = [
  {
    // The whole private-key block, body included (or to the end of a cut tail).
    pattern:
      /-----BEGIN [A-Z ]{0,40}PRIVATE KEY-----[\s\S]{0,4096}?(?:-----END [A-Z ]{0,40}PRIVATE KEY-----|$)/g,
    replacement: REDACTED,
  },
  // Credentials inside URLs and connection strings: scheme://user:<pass>@host.
  { pattern: /(\/\/[^\s:/@]{1,100}):[^\s@/]{1,200}@/g, replacement: `$1:${REDACTED}@` },
  // Secret-looking query parameters.
  {
    pattern:
      /([?&](?:token|key|api_?key|access_token|auth|sig|signature|session_?id|code|secret|password)=)[^&\s#'"]{1,500}/gi,
    replacement: `$1${REDACTED}`,
  },
  // Headers.
  {
    pattern: /\b((?:Proxy-)?Authorization\s*:\s*)(?:[A-Za-z]+\s+)?[^\s'"]{1,500}/gi,
    replacement: `$1${REDACTED}`,
  },
  { pattern: /\b((?:Set-)?Cookie\s*:\s*)[^\n]{1,500}/gi, replacement: `$1${REDACTED}` },
  { pattern: /\b(Bearer)\s+[A-Za-z0-9._~+/=-]{8,}/gi, replacement: `$1 ${REDACTED}` },
  // Known token prefixes.
  {
    pattern: /(?<![A-Za-z0-9_-])(?:sk|pk|rk)[-_](?:live_|test_|ant-)?[A-Za-z0-9_-]{16,}/g,
    replacement: REDACTED,
  },
  { pattern: /(?<![A-Za-z0-9_])gh[pousr]_[A-Za-z0-9]{20,}/g, replacement: REDACTED },
  { pattern: /(?<![A-Za-z0-9_])github_pat_[A-Za-z0-9_]{20,}/g, replacement: REDACTED },
  { pattern: /(?<![A-Za-z0-9_-])glpat-[A-Za-z0-9_-]{20,}/g, replacement: REDACTED },
  { pattern: /(?<![A-Za-z0-9_])npm_[A-Za-z0-9]{30,}/g, replacement: REDACTED },
  { pattern: /(?<![A-Za-z0-9_-])AIza[0-9A-Za-z_-]{30,}/g, replacement: REDACTED },
  { pattern: /(?<![A-Za-z0-9_-])ATATT[A-Za-z0-9_=-]{20,}/g, replacement: REDACTED },
  { pattern: /\bAKIA[0-9A-Z]{16}\b/g, replacement: REDACTED },
  { pattern: /(?<![A-Za-z0-9_-])xox[abposr]-[A-Za-z0-9-]{10,}/g, replacement: REDACTED },
  {
    pattern: /hooks\.slack\.com\/services\/[A-Za-z0-9/]{1,200}/g,
    replacement: `hooks.slack.com/services/${REDACTED}`,
  },
  {
    pattern: /(?<![A-Za-z0-9_-])eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{5,}/g,
    replacement: REDACTED,
  },
  // Command-line secrets: `--password x`, `--token=x`, `mysql -pX`.
  {
    pattern: /(--?(?:password|passwd|token|secret|api-key|access-key)(?:\s+|=))[^\s'"]{1,500}/gi,
    replacement: `$1${REDACTED}`,
  },
  {
    pattern: /(\bmysql\w{0,10}\s[^\n]{0,200}?\s)-p[^\s'"]{1,200}/gi,
    replacement: `$1-p${REDACTED}`,
  },
  // Named secrets in env, YAML, JSON or code: `DB_PASSWORD=x`, `"client_secret": "x"`, `token: x`.
  {
    pattern: new RegExp(
      `(?<![A-Za-z0-9])(${SECRET_NAME})(["']?\\s*[=:]\\s*["']?)[^\\s'"&,;]{1,500}`,
      `gi`,
    ),
    replacement: `$1$2${REDACTED}`,
  },
]

/** Every pattern in this module, for the adversarial-input (ReDoS) test. */
export const CORE_PATTERNS: readonly RegExp[] = [
  ANSI_CSI,
  ANSI_OSC,
  ANSI_SHORT,
  CONTROL_CHARS,
  ISO_TIMESTAMP,
  CLOCK_TIME,
  TIMING_LIST,
  TIMING_PAREN,
  TIMING_WORD,
  COMPOUND_DURATION,
  RELATIVE_TIME,
  TRAILING_MILLIS,
  GUARD_BLOCK,
  ...REFUSAL_TEXTS,
  INTERRUPT_TEXT,
  GIT_NAVIGATION,
  ATTEMPT_COUNTER,
  PROCESS_ID,
  RANDOM_SEED,
  UUID,
  MEMORY_ADDRESS,
  OBJECT_ID,
  LONG_HEX,
  TEMP_PATH,
  LOCAL_PORT,
  ABSOLUTE_PATH,
  SPACE_RUN,
  LINE_COLUMN,
  LINE_WORD,
  RUN_COUNTER,
  EXIT_CODE_PREFIX,
  EXPECTED_LINE,
  RECEIVED_LINE,
  ERROR_LINE,
  TEST_TITLE_LINE,
  ENVIRONMENT_HINT_LINE,
  ...SNIPPET_RANKING,
  TRAILING_LIMITER,
  TRAILING_STDERR_MERGE,
  LEADING_CD,
  VERIFICATION_COMMAND,
  POLL_COMMAND,
  ...CLASS_RULES.map(rule => rule.pattern),
  ...REDACTIONS.map(redaction => redaction.pattern),
]

/** The last `OUTPUT_TAIL_CHARS` of `text`: where failures surface, and all the core ever scans. */
export function tailOf(text: string): string {
  return text.length > OUTPUT_TAIL_CHARS ? text.slice(-OUTPUT_TAIL_CHARS) : text
}

/**
 * Cuts `text` to at most `max` characters, never splitting a surrogate pair,
 * and marks the cut with an ellipsis.
 */
export function truncate(text: string, max: number): string {
  if (text.length <= max) return text
  let end = max - 1
  const lastKept = text.charCodeAt(end - 1)
  if (lastKept >= HIGH_SURROGATE_FIRST && lastKept <= HIGH_SURROGATE_LAST) end -= 1
  return `${text.slice(0, end)}…`
}

/** Replaces secrets (keys, tokens, passwords, private keys) with `<redacted>`. */
export function redactSecrets(text: string): string {
  return REDACTIONS.reduce(
    (redacted, { pattern, replacement }) => redacted.replace(pattern, replacement),
    text,
  )
}

/**
 * A shell command reduced to what identifies the action: whitespace
 * collapsed, a leading `cd <dir> &&` dropped, and trailing output limiters
 * (`| tail -n 20`, `2>&1`) dropped, since re-running with a different limiter
 * is still the same action. Flags and arguments are kept verbatim.
 */
export function normalizeCommand(command: string): string {
  return tailOf(command)
    .trim()
    .replace(LEADING_CD, ``)
    .replace(TRAILING_LIMITER, ``)
    .replace(TRAILING_STDERR_MERGE, ``)
    .replace(SPACE_RUN, ` `)
}

/** Removes terminal escape sequences and keeps only what a carriage return left visible. */
function stripTerminal(text: string): string {
  return text
    .replace(ANSI_OSC, ``)
    .replace(ANSI_CSI, ``)
    .replace(ANSI_SHORT, ``)
    .split(`\n`)
    .map(
      line =>
        line
          .split(`\r`)
          .filter(part => part !== ``)
          .pop() ?? ``,
    )
    .join(`\n`)
    .replace(CONTROL_CHARS, ``)
}

/** An absolute path reduced to its last segments, so machines and temp roots don't matter. */
function shortenAbsolutePath(path: string): string {
  return `<abs>/${path.split(`/`).slice(-ABSOLUTE_PATH_KEPT_SEGMENTS).join(`/`)}`
}

/**
 * Output with volatile values replaced by placeholders, each in its own
 * context: timestamps (including npm's log-file names), timings and
 * relative times, retry counters, pids, seeds, ids, memory
 * addresses, temp paths, local ports and absolute-path prefixes. Two runs of
 * the same failure normalise to the same text, and different failures don't.
 * `file:line:col` is kept; `errorDigest` strips it for the coarse signature only.
 */
export function normalizeOutput(text: string): string {
  return stripTerminal(tailOf(text))
    .replace(ISO_TIMESTAMP, `<time>`)
    .replace(CLOCK_TIME, `<time>`)
    .replace(UUID, `<uuid>`)
    .replace(TEMP_PATH, `<tmp>`)
    .replace(LOCAL_PORT, `$1:<port>`)
    .replace(ABSOLUTE_PATH, shortenAbsolutePath)
    .replace(MEMORY_ADDRESS, `<addr>`)
    .replace(OBJECT_ID, `@<id>`)
    .replace(LONG_HEX, `<hex>`)
    .replace(TIMING_LIST, `(<timings>)`)
    .replace(TIMING_PAREN, `(<dur>)`)
    .replace(TIMING_WORD, `$1$2<dur>`)
    .replace(COMPOUND_DURATION, `<dur>`)
    .replace(RELATIVE_TIME, `<ago>`)
    .replace(ATTEMPT_COUNTER, `$1 <n>`)
    .replace(PROCESS_ID, `$1 <n>`)
    .replace(RANDOM_SEED, `$1 <n>`)
    .split(`\n`)
    .map(line => {
      const collapsed = line.replace(SPACE_RUN, ` `).trim()
      return TEST_TITLE_LINE.test(collapsed)
        ? collapsed.replace(TRAILING_MILLIS, ` <dur>`)
        : collapsed
    })
    .filter(line => line !== ``)
    .join(`\n`)
}

/** An environmental error class and the token it names (`pnpm`, `zod`), when one applies. */
export interface ErrorClassification {
  readonly errorClass?: ErrorClass
  readonly token?: string
}

/** What a failure's text is reduced to for fingerprints, classification and people. */
export interface ErrorDigest {
  /** The `Exit code N` a Bash failure starts with, when present. */
  readonly exitCode?: number
  /** Exact outcome input: exit code plus the full normalised text (keeps `file:line:col`). */
  readonly outcomeInput: string
  /**
   * Coarse identity from real error lines, with line/column numbers and run
   * counters stripped; absent when the output has no error lines at all.
   */
  readonly signatureInput?: string
  /** The most specific error line, redacted and capped at `SNIPPET_CAP`. */
  readonly snippet: string
  readonly classification: ErrorClassification
}

/** Splits the leading `Exit code N` (spike R3) off a Bash failure's text. */
function splitExitCode(text: string): { readonly exitCode?: number; readonly body: string } {
  const match = EXIT_CODE_PREFIX.exec(text)
  if (match?.[1] === undefined) return { body: text }
  return { exitCode: Number(match[1]), body: text.slice(match[0].length) }
}

/**
 * The most informative error line by `SNIPPET_RANKING`. An `Expected:` line is
 * joined with the `Received:` line that follows it ("Expected: 201 · Received: 500").
 */
function mostSpecificLine(errorLines: readonly string[]): string | undefined {
  for (const rank of SNIPPET_RANKING) {
    const index = errorLines.findIndex(line => rank.test(line))
    if (index === -1) continue
    const line = errorLines[index] ?? ``
    const next = errorLines[index + 1]
    return EXPECTED_LINE.test(line) && next !== undefined && RECEIVED_LINE.test(next)
      ? `${line}${SNIPPET_JOINER}${next}`
      : line
  }
  return errorLines[0]
}

/**
 * Classifies by the first class rule matching any of `lines`, first rule wins.
 * Callers pass only lines that can carry an environmental error.
 */
function classifyLines(lines: readonly string[]): ErrorClassification {
  for (const { errorClass, pattern } of CLASS_RULES) {
    for (const line of lines) {
      const match = pattern.exec(line)
      if (match === null) continue
      // Unmatched groups are undefined at run time, whatever `RegExpExecArray`'s type says.
      const groups: readonly (string | undefined)[] = match.slice(1)
      const token = groups.find(group => group !== undefined)
      return token === undefined ? { errorClass } : { errorClass, token }
    }
  }
  return {}
}

/** Whether a line can say something about the environment (not a test title or an assertion). */
function isClassifiable(line: string): boolean {
  return !TEST_TITLE_LINE.test(line) && !EXPECTED_LINE.test(line) && !RECEIVED_LINE.test(line)
}

/** Reduces a failure's text to its outcome input, error signature input, snippet and class. */
export function errorDigest(text: string): ErrorDigest {
  const { exitCode, body } = splitExitCode(tailOf(text))
  const normalized = normalizeOutput(body)
  const lines = normalized.split(`\n`).filter(line => line !== ``)
  const errorLines = lines.filter(line => ERROR_LINE.test(line)).slice(0, MAX_ERROR_LINES)
  // Environment lines (`HTTP/1.1 401 Unauthorized`, `Command timed out…`) also identify a failure.
  const signatureLines = lines
    .filter(line => ERROR_LINE.test(line) || ENVIRONMENT_HINT_LINE.test(line))
    .slice(0, MAX_ERROR_LINES)
  const signatureInput =
    signatureLines.length === 0
      ? undefined
      : signatureLines
          .map(line =>
            line
              .replace(LINE_COLUMN, `:<n>`)
              .replace(LINE_WORD, `$1 <n>`)
              .replace(RUN_COUNTER, `<n> $1`),
          )
          .join(`\n`)
  const exitLine = exitCode === undefined ? [] : [`Exit code ${String(exitCode)}`]
  const classifiable = [
    ...exitLine,
    ...lines.filter(line => ERROR_LINE.test(line) || ENVIRONMENT_HINT_LINE.test(line)),
  ]
    .filter(isClassifiable)
    .slice(-MAX_ERROR_LINES)
  const specific = mostSpecificLine(errorLines) ?? lines.at(-1) ?? ``
  const exitPart = exitCode === undefined ? `` : `exit ${String(exitCode)}|`
  return {
    ...(exitCode === undefined ? {} : { exitCode }),
    outcomeInput: `${exitPart}${normalized}`,
    ...(signatureInput === undefined ? {} : { signatureInput }),
    snippet: truncate(redactSecrets(specific), SNIPPET_CAP),
    classification: classifyLines(classifiable),
  }
}

/** Classifies a failure's text into an environmental error class (see `errorDigest`). */
export function classifyError(text: string): ErrorClassification {
  return errorDigest(text).classification
}

/** Whether a shell command runs tests, a build, a linter or a type checker. */
export function isVerificationCommand(command: string): boolean {
  return VERIFICATION_COMMAND.test(tailOf(command))
}

/** Whether a shell command only moves between versions (checkout, stash, bisect…): not a fix. */
export function isGitNavigationCommand(command: string): boolean {
  return GIT_NAVIGATION.test(tailOf(command))
}

/** Whether a shell command waits on something (sleep, watch, CI status, health checks). */
export function isPollCommand(command: string): boolean {
  return POLL_COMMAND.test(tailOf(command))
}

/**
 * Whether a failure is a PreToolUse hook refusing the call. A guard's block is
 * a denial: the action was never run, so retrying it differently is asking
 * the same guard again (security review and transcripts, Phase 3).
 */
export function isGuardBlock(text: string): boolean {
  return GUARD_BLOCK.test(text)
}

/**
 * What an error text says happened when it is not a failure of the tool: a
 * refusal (the person, a permission rule or auto mode said no) or an
 * interrupt. `undefined` for an ordinary error. Shared by the adapter and the
 * transcript miner so both read refusals the same way.
 */
export function refusalKindOf(text: string): `denied` | `interrupted` | undefined {
  // These texts lead the result, and a person's feedback after them can be long:
  // callers pass the whole text, never a tail.
  const head = text.slice(0, OUTPUT_TAIL_CHARS)
  if (REFUSAL_TEXTS.some(pattern => pattern.test(head))) return `denied`
  return INTERRUPT_TEXT.test(head) ? `interrupted` : undefined
}

