/**
 * The policy: a pure state machine per signature that turns signals into
 * decisions (nudge, escalate, stop, resolve).
 *
 * Ladder: a new signature at its nudge threshold is nudged once. When steering
 * is off or the turn's nudge budget is spent it is watched instead, and
 * nudged later once the budget frees up. At its escalation threshold it is
 * escalated to the user. If it continues `AUTO_STOP_DELTA` more times and
 * `autoStop` is on, the turn is stopped. `env-blocker` nudges and escalates
 * together, because the model usually cannot fix the environment.
 *
 * One streak of evidence → one response: a new signature whose evidence is
 * mostly covered by an earlier nudge or escalation in the same loop is
 * shadowed (silent). It is promoted to a normal signature once its own
 * uncovered evidence reaches the nudge threshold, so a loop that keeps going
 * under a different detector still escalates (Phase 2 review).
 */
import {
  AUTO_STOP_DELTA,
  COVERED_EVIDENCE_CAP,
  EVIDENCE_OVERLAP_LIMIT,
  IGNORED_CAP,
  MAX_NUDGES_PER_TURN,
  MAX_SIGNATURES,
} from './constants.ts'
import type { DetectorConfig } from './config.ts'
import { alertCopy, nudgeText } from './messages.ts'
import type {
  CallRecord,
  Decision,
  DetectorId,
  LoopId,
  PolicyState,
  ResolveWhen,
  Signal,
  SignatureState,
  Stage,
} from './types.ts'

/** A policy update: the next state and what the adapter should do. */
export interface PolicyStep {
  readonly policy: PolicyState
  readonly decisions: readonly Decision[]
}

/** Detectors whose signals are never shadowed: they ask for the user. */
const NEVER_SHADOWED: ReadonlySet<DetectorId> = new Set([`env-blocker`, `denied-retry`])

/** Stages in which the user has already been told. */
const TOLD_STAGES: ReadonlySet<Stage> = new Set([`escalated`, `stopped`])

/** Evidence in `evidence` not yet covered in `loopId`. */
function uncovered(
  policy: PolicyState,
  loopId: LoopId,
  evidence: readonly string[],
): readonly string[] {
  const covered = new Set(policy.covered[loopId] ?? [])
  return evidence.filter(id => !covered.has(id))
}

/** Whether a new signal mostly repeats evidence an earlier response already covered. */
function isMostlyCovered(policy: PolicyState, signal: Signal): boolean {
  if (NEVER_SHADOWED.has(signal.detector) || signal.evidence.length === 0) return false
  const coveredShare =
    1 - uncovered(policy, signal.loopId, signal.evidence).length / signal.evidence.length
  return coveredShare >= EVIDENCE_OVERLAP_LIMIT
}

/** Records `evidence` as covered in its loop. */
function cover(policy: PolicyState, loopId: LoopId, evidence: readonly string[]): PolicyState {
  const merged = [...new Set([...(policy.covered[loopId] ?? []), ...evidence])].slice(
    -COVERED_EVIDENCE_CAP,
  )
  return { ...policy, covered: { ...policy.covered, [loopId]: merged } }
}

/** Stores a signature's state, keeping at most `MAX_SIGNATURES` (least recently seen dropped). */
function withSignature(policy: PolicyState, state: SignatureState): PolicyState {
  const signatures = { ...policy.signatures, [state.signature]: state }
  const keys = Object.keys(signatures)
  if (keys.length <= MAX_SIGNATURES) return { ...policy, signatures }
  const kept = Object.values(signatures)
    .sort((a, b) => b.lastAt - a.lastAt)
    .slice(0, MAX_SIGNATURES)
  return { ...policy, signatures: Object.fromEntries(kept.map(kept => [kept.signature, kept])) }
}

/** A signature's state from a signal. */
function stateFrom(
  signal: Signal,
  stage: Stage,
  wasNudged: boolean,
  now: number,
  firstAt = now,
): SignatureState {
  return {
    signature: signal.signature,
    detector: signal.detector,
    loopId: signal.loopId,
    stage,
    count: signal.count,
    wasNudged,
    resolveWhen: signal.resolveWhen,
    firstAt,
    lastAt: now,
  }
}

/** Whether a nudge may be sent now. */
function canNudge(policy: PolicyState, config: DetectorConfig): boolean {
  return config.steer && policy.nudgesThisTurn < MAX_NUDGES_PER_TURN
}

/** The nudge decision for a signal, spending one of the turn's nudges. */
function nudge(policy: PolicyState, signal: Signal): PolicyStep {
  return {
    policy: { ...policy, nudgesThisTurn: policy.nudgesThisTurn + 1 },
    decisions: [{ kind: `nudge`, signal, text: nudgeText(signal) }],
  }
}

/** The escalation decision for a signal. */
function escalation(signal: Signal): Decision {
  return { kind: `escalate`, signal, alert: alertCopy(signal) }
}

/** A signature responded to for the first time (new, or promoted out of the shadow). */
function respond(
  policy: PolicyState,
  signal: Signal,
  config: DetectorConfig,
  now: number,
  firstAt: number,
): PolicyStep {
  const covered = cover(policy, signal.loopId, signal.evidence)

  if (signal.detector === `env-blocker`) {
    const nudged = canNudge(covered, config)
      ? nudge(covered, signal)
      : { policy: covered, decisions: [] }
    const wasNudged = nudged.decisions.length > 0
    return {
      policy: withSignature(nudged.policy, stateFrom(signal, `escalated`, wasNudged, now, firstAt)),
      decisions: [...nudged.decisions, escalation(signal)],
    }
  }

  if (signal.count >= signal.escalateAt) {
    return {
      policy: withSignature(covered, stateFrom(signal, `escalated`, false, now, firstAt)),
      decisions: [escalation(signal)],
    }
  }

  if (canNudge(covered, config)) {
    const nudged = nudge(covered, signal)
    return {
      policy: withSignature(nudged.policy, stateFrom(signal, `nudged`, true, now, firstAt)),
      decisions: nudged.decisions,
    }
  }

  return {
    policy: withSignature(covered, stateFrom(signal, `watching`, false, now, firstAt)),
    decisions: [],
  }
}

/** A recurrence of a signature the policy already knows. */
function laterSignal(
  policy: PolicyState,
  known: SignatureState,
  signal: Signal,
  config: DetectorConfig,
  now: number,
): PolicyStep {
  const keep = (stage: Stage, wasNudged = known.wasNudged): PolicyState =>
    withSignature(policy, stateFrom(signal, stage, wasNudged, now, known.firstAt))

  if (known.stage === `shadowed`) {
    const ownEvidence = uncovered(policy, signal.loopId, signal.evidence)
    return ownEvidence.length >= signal.nudgeAt
      ? respond(policy, signal, config, now, known.firstAt)
      : { policy: keep(`shadowed`), decisions: [] }
  }

  if (!TOLD_STAGES.has(known.stage) && signal.count >= signal.escalateAt) {
    return {
      policy: withSignature(
        cover(policy, signal.loopId, signal.evidence),
        stateFrom(signal, `escalated`, known.wasNudged, now, known.firstAt),
      ),
      decisions: [escalation(signal)],
    }
  }

  if (known.stage === `watching` && canNudge(policy, config)) {
    const nudged = nudge(policy, signal)
    return {
      policy: withSignature(nudged.policy, stateFrom(signal, `nudged`, true, now, known.firstAt)),
      decisions: nudged.decisions,
    }
  }

  if (
    known.stage === `escalated` &&
    config.autoStop &&
    signal.count >= signal.escalateAt + AUTO_STOP_DELTA
  ) {
    return { policy: keep(`stopped`), decisions: [{ kind: `stop`, signal }] }
  }

  return { policy: keep(known.stage), decisions: [] }
}

/**
 * Applies a detector's signal.
 *
 * @param now the adapter's clock, for first/last-seen times
 */
export function applySignal(
  policy: PolicyState,
  signal: Signal,
  config: DetectorConfig,
  now: number,
): PolicyStep {
  if (policy.isPaused || policy.ignored.includes(signal.signature)) return { policy, decisions: [] }
  const known = policy.signatures[signal.signature]
  if (known !== undefined) return laterSignal(policy, known, signal, config, now)
  if (isMostlyCovered(policy, signal)) {
    return {
      policy: withSignature(policy, stateFrom(signal, `shadowed`, false, now)),
      decisions: [],
    }
  }
  return respond(policy, signal, config, now, now)
}

/** Whether `record` shows the loop behind `resolveWhen` is broken. */
function isResolvedBy(resolveWhen: ResolveWhen, record: CallRecord): boolean {
  switch (resolveWhen.kind) {
    case `action-succeeds`:
      return record.argsKey === resolveWhen.argsKey && record.outcome === `ok`
    case `output-changes`:
      return record.argsKey === resolveWhen.argsKey && record.outcomeFp !== resolveWhen.outcomeFp
    case `error-changes`:
      return (
        (resolveWhen.argsKeys.includes(record.argsKey) || record.isVerification) &&
        (record.outcome === `ok` ||
          (record.errorSig !== undefined && record.errorSig !== resolveWhen.errorSig))
      )
    case `user-prompt`:
      return false
  }
}

/**
 * Checks a new record against every open signature of its loop and resolves
 * the ones it breaks. A resolved signature is forgotten, so a later
 * recurrence starts a fresh streak.
 */
export function applyRecord(policy: PolicyState, record: CallRecord): PolicyStep {
  const decisions: Decision[] = []
  const signatures: Record<string, SignatureState> = {}
  for (const [signature, state] of Object.entries(policy.signatures)) {
    if (state.loopId === record.loopId && isResolvedBy(state.resolveWhen, record)) {
      if (state.stage !== `shadowed`) {
        decisions.push({
          kind: `resolve`,
          signature,
          detector: state.detector,
          loopId: state.loopId,
          wasNudged: state.wasNudged,
        })
      }
      continue
    }
    signatures[signature] = state
  }
  return { policy: decisions.length === 0 ? policy : { ...policy, signatures }, decisions }
}

/**
 * Forgets signatures and covered evidence of loops that are no longer
 * tracked (evicted subagents), so the policy never outgrows the windows.
 */
export function pruneLoops(policy: PolicyState, liveLoops: ReadonlySet<LoopId>): PolicyState {
  const signatures = Object.fromEntries(
    Object.entries(policy.signatures).filter(([, state]) => liveLoops.has(state.loopId)),
  )
  const covered = Object.fromEntries(
    Object.entries(policy.covered).filter(([loopId]) => liveLoops.has(loopId)),
  )
  const isUnchanged =
    Object.keys(signatures).length === Object.keys(policy.signatures).length &&
    Object.keys(covered).length === Object.keys(policy.covered).length
  return isUnchanged ? policy : { ...policy, signatures, covered }
}

/**
 * A new prompt from the person: every streak starts over (signatures and
 * covered evidence forgotten), the turn's nudge budget resets, and ignores
 * and pause stay.
 */
export function applyUserPrompt(policy: PolicyState): PolicyState {
  return { ...policy, signatures: {}, covered: {}, nudgesThisTurn: 0 }
}

/** The turn ended: its nudge budget resets. */
export function applyTurnEnd(policy: PolicyState): PolicyState {
  return { ...policy, nudgesThisTurn: 0 }
}

/** The person chose Ignore: this signature stays silent for the session. */
export function ignoreSignature(policy: PolicyState, signature: string): PolicyState {
  const { [signature]: _dropped, ...signatures } = policy.signatures
  const ignored = [...new Set([...policy.ignored, signature])].slice(-IGNORED_CAP)
  return { ...policy, signatures, ignored }
}

/** Pauses or resumes detection for the session (`/loop-breaker off|on`). */
export function setPaused(policy: PolicyState, isPaused: boolean): PolicyState {
  return { ...policy, isPaused }
}

