/**
 * Per-file edit history for the edit-thrash detector.
 *
 * The core never reads files. It reconstructs content states from what the
 * engine hands back: an Edit's `originalFile` (the content before the edit,
 * spike R4) plus its `old_string`/`new_string`, and a Write's `content`.
 *
 * Thrash is **alternation**: a run of edits where each one exactly undoes the
 * edit before it (A→B, B→A, A→B, …). Undoing an edit once and moving on is
 * normal work: add a debug log, run the tests, remove the log, make the real
 * fix. That gives runs of length 1 and never reaches a threshold. No-op saves
 * and failed edits are not recorded at all (Phase 2 review).
 */
import { FILE_HISTORY_CAP } from './constants.ts'
import type { CallRecord, FileEdit, FileHistory } from './types.ts'

/**
 * The content after replacing `oldString` with `newString`, exactly as the
 * Edit tool does. It splices by index rather than `String.replace`, whose
 * `$&`-style patterns would corrupt a `newString` that contains them.
 *
 * @returns the new content, or `undefined` when `oldString` is not present
 */
export function applyEdit(
  original: string,
  oldString: string,
  newString: string,
  replaceAll: boolean,
): string | undefined {
  if (oldString === ``) return undefined
  const first = original.indexOf(oldString)
  if (first === -1) return undefined
  if (replaceAll) return original.split(oldString).join(newString)
  return original.slice(0, first) + newString + original.slice(first + oldString.length)
}

/** A history with nothing recorded yet. */
export function emptyFileHistory(now: number): FileHistory {
  return { edits: [], touchedAt: now }
}

/**
 * Adds one successful Edit/Write to a file's history. Failed calls and saves
 * that leave the content unchanged are skipped.
 */
export function recordFileChange(history: FileHistory, record: CallRecord): FileHistory {
  if (record.outcome !== `ok`) return history
  const isNoOp =
    record.fileHashBefore !== undefined && record.fileHashBefore === record.fileHashAfter
  if (isNoOp) return history
  const edit: FileEdit = {
    id: record.id,
    ...(record.fileHashBefore === undefined ? {} : { before: record.fileHashBefore }),
    ...(record.fileHashAfter === undefined ? {} : { after: record.fileHashAfter }),
    ...(record.editPair === undefined ? {} : { pair: record.editPair }),
  }
  const edits = [...history.edits, edit]
  return {
    edits: edits.length > FILE_HISTORY_CAP ? edits.slice(-FILE_HISTORY_CAP) : edits,
    touchedAt: record.at,
  }
}

/** Whether `current` exactly undoes `previous`, by content states or by inverted replacement. */
export function isFlipBack(previous: FileEdit, current: FileEdit): boolean {
  const byStates =
    current.before !== undefined &&
    current.after !== undefined &&
    current.before === previous.after &&
    current.after === previous.before
  const byPairs =
    current.pair !== undefined &&
    previous.pair !== undefined &&
    current.pair[0] === previous.pair[1] &&
    current.pair[1] === previous.pair[0]
  return byStates || byPairs
}

/**
 * The trailing run of flip-backs among the edits whose calls are still in the
 * window: each edit in the run undid the one before it.
 */
export function flipBackRun(
  history: FileHistory,
  liveIds: ReadonlySet<string>,
): readonly FileEdit[] {
  const edits = history.edits.filter(edit => liveIds.has(edit.id))
  const run: FileEdit[] = []
  for (let index = edits.length - 1; index > 0; index -= 1) {
    const current = edits[index]
    const previous = edits[index - 1]
    if (current === undefined || previous === undefined || !isFlipBack(previous, current)) break
    run.unshift(current)
  }
  return run
}

