/**
 * cycle: a short sequence of actions (period 2–4) repeating with the same
 * outcomes, e.g. read config → run tests (same failure) → read config → …
 * (Gemini CLI cycles 1–5, OpenHands alternating, OpenClaw ping-pong).
 * Period 1 is a plain repeat and belongs to the other detectors.
 */
import { CYCLE_PERIODS } from '../constants.ts'
import { hashText } from '../hash.ts'
import type { CallRecord } from '../types.ts'
import type { Detector } from './shared.ts'
import { nonPollRecords, signalWhenDue } from './shared.ts'

/** A cycle repeats at least this many different actions (period 1 or one action is a repeat). */
const MIN_CYCLE_ACTIONS = 2

/** An action and what it produced: two steps match only when both match. */
function stepKey(record: CallRecord): string {
  return `${record.argsKey}|${record.outcomeFp}`
}

/**
 * The pattern's smallest rotation, so a running cycle keeps one signature:
 * A→B→A→B ends on `[A,B]` at one step and `[B,A]` at the next.
 */
function canonicalRotation(pattern: readonly string[]): string {
  const rotations = pattern.map((_key, start) =>
    [...pattern.slice(start), ...pattern.slice(0, start)].join(`>`),
  )
  return rotations.reduce((smallest, rotation) => (rotation < smallest ? rotation : smallest))
}

/** How many times the last `period` steps repeat back to back at the end of `keys`. */
function repetitions(keys: readonly string[], period: number): number {
  const pattern = keys.slice(-period)
  if (pattern.length < period || new Set(pattern).size < 2) return 0
  let count = 1
  while (keys.length >= (count + 1) * period) {
    const end = keys.length - count * period
    const block = keys.slice(end - period, end)
    if (block.some((key, index) => key !== pattern[index])) break
    count += 1
  }
  return count
}

export const cycle: Detector = {
  id: `cycle`,
  detect: (window, record, config) => {
    if (record.isPoll) return undefined
    const records = nonPollRecords(window)
    const keys = records.map(stepKey)
    for (const period of CYCLE_PERIODS) {
      const count = repetitions(keys, period)
      if (count < config.thresholds.cycle.nudge) continue
      // One action alternating outcomes (a flaky test) is not a cycle of steps.
      const distinctActions = new Set(records.slice(-period).map(step => step.argsKey))
      if (distinctActions.size < MIN_CYCLE_ACTIONS) continue
      const evidence = records.slice(-count * period)
      const labels = [...new Set(evidence.slice(-period).map(step => step.label))]
      return signalWhenDue(`cycle`, record, {
        key: hashText(canonicalRotation(keys.slice(-period))),
        count,
        ladder: config.thresholds.cycle,
        evidence,
        label: labels.join(` → `),
        resolveWhen: { kind: `user-prompt` },
      })
    }
    return undefined
  },
}

files.hooks/core/detectors/denied-retry.ts:
/**
 * denied-retry: an action the user or a guard refused, attempted again.
 * The right move is to ask, not to retry (opencode/Roo ask-the-user pattern).
 *
 * Two ways to retry:
 * - the same action again, anywhere since the last prompt;
 * - when the refusal carries a reason (a PreToolUse hook's block, an auto
 *   mode classifier's verdict), the same tool refused for the same reason
 *   back to back. Rewording a blocked `.env` edit asks the same guard again
 *   (Phase 3 review, I5); doing what a guard asks in between (activating a
 *   skill, reading the file) is progress, even when the guard then asks for
 *   more (mined transcripts: guards are met and satisfied routinely).
 *
 * Calls issued together count as one attempt (`countAttempts`). A person's
 * or a classifier's no is final, so one retry is already a loop (the
 * `deniedRetry` ladder). A hook's block is procedural ("activate the skill,
 * then retry your edit"), so a retry after it is expected and only a streak
 * of them is a loop: the `repeatFailure` ladder.
 */
import type { CallRecord } from '../types.ts'
import type { Detector } from './shared.ts'
import { countAttempts, signalWhenDue } from './shared.ts'

/** Earlier refusals of exactly this action. */
function sameActionDenials(
  records: readonly CallRecord[],
  record: CallRecord,
): readonly CallRecord[] {
  return records.filter(other => other.outcome === `denied` && other.argsKey === record.argsKey)
}

/**
 * Back-to-back refusals of this tool for this reason. Any success in between
 * (a Skill activated, a file read, an edit landed) breaks the streak: the
 * agent did something about the refusal, even if the guard asks for more.
 */
function sameReasonStreak(
  records: readonly CallRecord[],
  record: CallRecord,
): readonly CallRecord[] {
  const streak: CallRecord[] = []
  for (let index = records.length - 1; index >= 0; index -= 1) {
    const other = records[index]
    if (other === undefined) break
    const isSameRefusal =
      other.outcome === `denied` && other.tool === record.tool && other.errorSig === record.errorSig
    if (isSameRefusal) {
      streak.unshift(other)
      continue
    }
    if (other.outcome === `ok` || other.tool === record.tool) break
  }
  return streak
}

export const deniedRetry: Detector = {
  id: `denied-retry`,
  detect: (window, record, config) => {
    if (record.outcome !== `denied`) return undefined
    const sameAction = sameActionDenials(window.records, record)
    const sameReason = record.errorSig === undefined ? [] : sameReasonStreak(window.records, record)
    const isByReason = sameReason.length > sameAction.length
    const denials = isByReason ? sameReason : sameAction
    const { deniedRetry: final, repeatFailure: procedural } = config.thresholds
    return signalWhenDue(`denied-retry`, record, {
      key: isByReason ? `reason:${record.errorSig ?? ``}` : `args:${record.argsKey}`,
      count: countAttempts(denials),
      ladder: record.isGuardBlock ? procedural : final,
      evidence: denials,
      label: record.label,
      resolveWhen: { kind: `action-succeeds`, argsKey: record.argsKey },
    })
  },
}

files.hooks/core/detectors/edit-thrash.ts:
/**
 * edit-thrash: edits that keep undoing each other: A→B, B→A, A→B, …, a
 * run of consecutive flip-backs in one file (OpenHands edit comparison;
 * arXiv 2603.24631 saw agents write the right patch, then destroy it).
 * Undoing once and moving on (debug-log cleanup) is a run of 1 and never
 * fires. Only edits still in the window count.
 */
import { flipBackRun } from '../file-tracker.ts'
import { hashText } from '../hash.ts'
import type { Detector } from './shared.ts'
import { signalWhenDue } from './shared.ts'

export const editThrash: Detector = {
  id: `edit-thrash`,
  detect: (window, record, config) => {
    if (!record.isEdit || record.file === undefined || record.outcome !== `ok`) return undefined
    const history = window.files[record.file]
    if (history === undefined) return undefined
    const run = flipBackRun(history, new Set(window.records.map(other => other.id)))
    if (run.at(-1)?.id !== record.id) return undefined
    const runIds = new Set(run.map(edit => edit.id))
    return signalWhenDue(`edit-thrash`, record, {
      key: hashText(record.file),
      count: run.length,
      ladder: config.thresholds.editThrash,
      evidence: window.records.filter(other => runIds.has(other.id)),
      label: record.label,
      resolveWhen: { kind: `user-prompt` },
    })
  },
}

files.hooks/core/detectors/env-blocker.ts:
/**
 * env-blocker: the same environmental error across recent failures of
 * **different** actions. The model usually can't fix these, so the policy
 * nudges and escalates together. Two families:
 *
 * - **Bash**: a missing command or package, a refused connection, failing
 *   auth, a full disk or a timeout on the local machine.
 * - **MCP**: one server failing the same way across several of its tools
 *   (Chrome not running, an expired token): the server is the blocker.
 *
 * Precision rules (Phase 2 and Phase 3 reviews):
 * - Web tools never count: a fetch hitting 403 on three sites is research,
 *   not a local blocker. MCP needs two different tools of one server, so
 *   404s on different Jira keys through one tool are not a blocker either.
 * - At least two different actions: one command re-run while fixing code
 *   (a deadlock "timeout", a 401 in a token-refresh test) is a code loop for
 *   repeat-failure/same-error, never "Claude can't fix this one".
 * - Bash hits must agree on the token the error names (`pnpm`, `zod`).
 *   Token-less classes (a refused connection, permissions, auth) agree on
 *   the class alone, because each tool words them its own way (jest, knex
 *   and prisma on a database that is down), but only after the last state
 *   change: an edit in between means the code is being worked on. MCP hits
 *   must share the error signature, also since the last state change.
 */
import { ENV_BLOCKER_SPAN } from '../constants.ts'
import type { CallRecord } from '../types.ts'
import type { Detector } from './shared.ts'
import {
  changesState,
  countAttempts,
  nonPollRecords,
  signalWhenDue,
  trailingRun,
} from './shared.ts'

const MIN_DISTINCT_ACTIONS = 2
const MCP_PREFIX = `mcp`
const MCP_SEPARATOR = `__`

/** The MCP server a tool belongs to (`mcp__chrome__list_pages` → `chrome`), if any. */
function mcpServer(tool: string): string | undefined {
  const [prefix, server] = tool.split(MCP_SEPARATOR)
  return prefix === MCP_PREFIX && server !== undefined && server !== `` ? server : undefined
}

/** A blocker found among recent records. */
interface Blocker {
  readonly key: string
  readonly label: string
  readonly matches: readonly CallRecord[]
  readonly distinct: number
}

/** Bash failures sharing `record`'s environmental class (and token, when it names one). */
function bashBlocker(recent: readonly CallRecord[], record: CallRecord): Blocker | undefined {
  const { errorClass, errorToken } = record
  if (record.tool !== `Bash` || errorClass === undefined) return undefined
  const scope =
    errorToken === undefined ? trailingRun(recent, other => !changesState(other)) : recent
  const matches = scope.filter(
    other =>
      other.tool === `Bash` &&
      other.outcome === `error` &&
      other.errorClass === errorClass &&
      (errorToken === undefined || other.errorToken === errorToken),
  )
  return {
    key: `${errorClass}:${errorToken ?? ``}`,
    label: errorToken ?? errorClass,
    matches,
    distinct: new Set(matches.map(other => other.argsKey)).size,
  }
}

/** Failures of one MCP server's tools sharing `record`'s error signature. */
function mcpBlocker(recent: readonly CallRecord[], record: CallRecord): Blocker | undefined {
  const server = mcpServer(record.tool)
  const { errorSig } = record
  if (server === undefined || errorSig === undefined) return undefined
  const matches = trailingRun(recent, other => !changesState(other)).filter(
    other =>
      other.outcome === `error` && other.errorSig === errorSig && mcpServer(other.tool) === server,
  )
  return {
    key: `mcp:${server}:${errorSig}`,
    label: `${server} (MCP)`,
    matches,
    distinct: new Set(matches.map(other => other.tool)).size,
  }
}

export const envBlocker: Detector = {
  id: `env-blocker`,
  detect: (window, record, config) => {
    if (record.isPoll || record.outcome !== `error`) return undefined
    const recent = nonPollRecords(window).slice(-ENV_BLOCKER_SPAN)
    const blocker = bashBlocker(recent, record) ?? mcpBlocker(recent, record)
    if (blocker === undefined || blocker.distinct < MIN_DISTINCT_ACTIONS) return undefined
    const threshold = config.thresholds.envBlocker
    return signalWhenDue(`env-blocker`, record, {
      key: blocker.key,
      // Calls issued together are one attempt: three parallel calls to a dead server are one try.
      count: countAttempts(blocker.matches),
      ladder: { nudge: threshold, escalate: threshold },
      evidence: blocker.matches,
      label: blocker.label,
      resolveWhen: { kind: `user-prompt` },
    })
  },
}

