/**
 * idle-repeat: the same successful action returning the same output again
 * and again with nothing changed in between (Claude Code issue #59318: the
 * same grep 30+ times). Any other state-changing call resets it (an edit,
 * `sed -i`, …). Wasted steps, low risk, so its ladder is higher (5 → 10).
 */
import type { Detector } from './shared.ts'
import { changesState, nonPollRecords, signalWhenDue, trailingRun } from './shared.ts'

export const idleRepeat: Detector = {
  id: `idle-repeat`,
  detect: (window, record, config) => {
    if (record.isPoll || record.isEdit || record.outcome !== `ok`) return undefined
    const sinceLastChange = trailingRun(
      nonPollRecords(window),
      other => other.argsKey === record.argsKey || !changesState(other),
    )
    const repeats = sinceLastChange.filter(
      other =>
        other.outcome === `ok` &&
        other.argsKey === record.argsKey &&
        other.outcomeFp === record.outcomeFp,
    )
    return signalWhenDue(`idle-repeat`, record, {
      key: record.argsKey,
      count: repeats.length,
      ladder: config.thresholds.idleRepeat,
      evidence: repeats,
      label: record.label,
      resolveWhen: { kind: `output-changes`, argsKey: record.argsKey, outcomeFp: record.outcomeFp },
    })
  },
}

