/**
 * poll: waiting tools and commands (sleep, watch, CI status, health checks,
 * Monitor/TaskGet) counted only while their output stays the same, at a high
 * ladder (10 → 20, OpenClaw's known-poll class). Changing output is progress.
 */
import type { Detector } from './shared.ts'
import { signalWhenDue, trailingRun } from './shared.ts'

export const poll: Detector = {
  id: `poll`,
  detect: (window, record, config) => {
    if (!record.isPoll) return undefined
    const samePoll = window.records.filter(
      other => other.isPoll && other.argsKey === record.argsKey,
    )
    const unchanged = trailingRun(samePoll, other => other.outcomeFp === record.outcomeFp)
    return signalWhenDue(`poll`, record, {
      key: record.argsKey,
      count: unchanged.length,
      ladder: config.thresholds.poll,
      evidence: unchanged,
      label: record.label,
      resolveWhen: { kind: `output-changes`, argsKey: record.argsKey, outcomeFp: record.outcomeFp },
    })
  },
}

