/**
 * repeat-failure: the same action failing with the same exact outcome, again
 * and again (Cline 3/5, OpenHands action-error, Crush, OpenClaw). Read-only
 * calls in between (reading files, `git status`) don't break the run, because
 * they change nothing. A success, a different outcome or any other kind of
 * call does: that is progress.
 */
import type { CallRecord } from '../types.ts'
import type { Detector } from './shared.ts'
import { nonPollRecords, signalWhenDue } from './shared.ts'

/** The run of identical failures ending at `record`, looking past read-only observation. */
function identicalFailures(
  records: readonly CallRecord[],
  record: CallRecord,
): readonly CallRecord[] {
  const run: CallRecord[] = []
  for (let index = records.length - 1; index >= 0; index -= 1) {
    const other = records[index]
    if (other === undefined) break
    if (other.argsKey === record.argsKey) {
      if (other.outcome !== `error` || other.outcomeFp !== record.outcomeFp) break
      run.unshift(other)
      continue
    }
    if (!other.isReadOnly || other.isEdit) break
  }
  return run
}

export const repeatFailure: Detector = {
  id: `repeat-failure`,
  detect: (window, record, config) => {
    if (record.isPoll || record.outcome !== `error`) return undefined
    const run = identicalFailures(nonPollRecords(window), record)
    return signalWhenDue(`repeat-failure`, record, {
      key: record.argsKey,
      count: run.length,
      ladder: config.thresholds.repeatFailure,
      evidence: run,
      label: record.label,
      resolveWhen: { kind: `output-changes`, argsKey: record.argsKey, outcomeFp: record.outcomeFp },
    })
  },
}

