/**
 * same-error: the same coarse error signature keeps coming back while the
 * attempts change: "repairs the wrong problem", 39% of wasted steps in
 * arXiv 2607.09510 (OpenClaw failureIdentityHash).
 *
 * (a) consecutive failed Bash calls with different args and one signature
 *     built from real error lines. Read-only calls are excluded (exploring is
 *     not repairing), and so are other tools: web and MCP lookups failing the
 *     same way on different inputs (404s, 403s) are research, not repair.
 *     Bash-only also keeps this path independent of how the engine flags
 *     MCP tools' read-only status.
 * (b) verification reruns (test/build/lint/typecheck) with an unchanged
 *     signature and a state change (an edit, `sed -i`, …) between each run.
 *     Moving between versions (`git checkout`, `stash`, `bisect`) is not a
 *     fix: the same failure on several commits is what bisecting shows.
 * A changed signature breaks the streak (OpenClaw churn reset).
 */
import type { CallRecord } from '../types.ts'
import type { Detector } from './shared.ts'
import { changesState, nonPollRecords, signalWhenDue, trailingRun } from './shared.ts'

/** (a): consecutive failures of one tool sharing the signature, across at least two different actions. */
function acrossAttempts(records: readonly CallRecord[], record: CallRecord): readonly CallRecord[] {
  if (record.tool !== `Bash` || record.isReadOnly) return []
  const run = trailingRun(
    records,
    other =>
      other.outcome === `error` &&
      !other.isReadOnly &&
      other.tool === record.tool &&
      other.errorSig === record.errorSig,
  )
  const distinctActions = new Set(run.map(other => other.argsKey))
  return distinctActions.size >= 2 ? run : []
}

/** (b): verification reruns, newest backwards, each separated from the next by a state change. */
function acrossFixes(records: readonly CallRecord[], record: CallRecord): readonly CallRecord[] {
  if (!record.isVerification) return []
  const runs: CallRecord[] = [record]
  let sawChange = false
  for (let index = records.length - 2; index >= 0; index -= 1) {
    const other = records[index]
    if (other === undefined) break
    if (other.isVerification) {
      if (other.outcome !== `error` || other.errorSig !== record.errorSig || !sawChange) break
      runs.unshift(other)
      sawChange = false
      continue
    }
    if (changesState(other) && !other.isNavigation) sawChange = true
  }
  return runs
}

export const sameError: Detector = {
  id: `same-error`,
  detect: (window, record, config) => {
    const { errorSig } = record
    if (record.isPoll || record.outcome !== `error` || errorSig === undefined) return undefined
    const records = nonPollRecords(window)
    const attempts = acrossAttempts(records, record)
    const isAttempts = attempts.length > 0
    const run = isAttempts ? attempts : acrossFixes(records, record)
    return signalWhenDue(`same-error`, record, {
      key: errorSig,
      count: run.length,
      ladder: isAttempts ? config.thresholds.sameError : config.thresholds.sameErrorVerification,
      evidence: run,
      label: record.label,
      resolveWhen: {
        kind: `error-changes`,
        errorSig,
        argsKeys: [...new Set(run.map(other => other.argsKey))],
      },
    })
  },
}

