/**
 * The detector contract and helpers every detector shares.
 */
import type { DetectorConfig, Ladder } from '../config.ts'
import type { CallRecord, DetectorId, LoopId, LoopWindow, ResolveWhen, Signal } from '../types.ts'

/**
 * One loop detector. `detect` sees the window with the newest record already
 * appended, and returns a signal once its count reaches the nudge threshold.
 * The policy decides what the signal leads to.
 */
export interface Detector {
  readonly id: DetectorId
  readonly detect: (
    window: LoopWindow,
    record: CallRecord,
    config: DetectorConfig,
  ) => Signal | undefined
}

/** The window's records other than polls, in order. Polls belong to the poll class alone. */
export function nonPollRecords(window: LoopWindow): readonly CallRecord[] {
  return window.records.filter(record => !record.isPoll)
}

/**
 * The longest run at the end of `records` (newest backwards) whose members
 * all satisfy `belongs`.
 */
export function trailingRun(
  records: readonly CallRecord[],
  belongs: (record: CallRecord) => boolean,
): readonly CallRecord[] {
  let start = records.length
  while (start > 0) {
    const previous = records[start - 1]
    if (previous === undefined || !belongs(previous)) break
    start -= 1
  }
  return records.slice(start)
}

/**
 * Whether a call changed something: any edit, or a successful call the engine
 * did not hold read-only (`sed -i`, `npm install`, a migration). Changes are
 * progress between reruns; read-only calls are just observation.
 */
export function changesState(record: CallRecord): boolean {
  return record.isEdit || (record.outcome === `ok` && !record.isReadOnly)
}

/**
 * How many attempts `records` (matching calls, in order) amount to. A call
 * issued before the previous one's result arrived (several calls in one
 * message) joins that attempt: the model had not seen the result yet, so it
 * cannot have ignored it. 11 of 33 back-to-back guard blocks in mined
 * transcripts were such siblings.
 */
export function countAttempts(records: readonly CallRecord[]): number {
  let attempts = 0
  let previous: CallRecord | undefined
  for (const record of records) {
    const isSibling =
      previous !== undefined && record.startedAt !== undefined && record.startedAt < previous.at
    if (!isSibling) attempts += 1
    previous = record
  }
  return attempts
}

/** A signature: stable across reloads, unique per loop. */
export function signatureOf(detector: DetectorId, loopId: LoopId, key: string): string {
  return `${detector}:${loopId}:${key}`
}

/** What a signal carries beyond the shared fields. */
interface SignalParts {
  readonly key: string
  readonly count: number
  readonly ladder: Ladder
  readonly evidence: readonly CallRecord[]
  readonly label: string
  readonly resolveWhen: ResolveWhen
}

/**
 * Builds a signal when `count` has reached the ladder's nudge threshold.
 *
 * @returns the signal, or `undefined` below the threshold
 */
export function signalWhenDue(
  detector: DetectorId,
  record: CallRecord,
  { key, count, ladder, evidence, label, resolveWhen }: SignalParts,
): Signal | undefined {
  if (count < ladder.nudge) return undefined
  return {
    detector,
    signature: signatureOf(detector, record.loopId, key),
    loopId: record.loopId,
    count,
    nudgeAt: ladder.nudge,
    escalateAt: ladder.escalate,
    evidence: evidence.map(item => item.id),
    label,
    ...(record.snippet === undefined ? {} : { snippet: record.snippet }),
    ...(record.errorClass === undefined ? {} : { errorClass: record.errorClass }),
    ...(record.errorToken === undefined ? {} : { errorToken: record.errorToken }),
    resolveWhen,
  }
}

