/**
 * A fast, synchronous, non-cryptographic hash for fingerprints.
 *
 * Two FNV-1a lanes over UTF-16 code units, with different offset bases,
 * combined into a 16-hex-character id (about 64 bits). It is synchronous on
 * purpose: `crypto.subtle` is async and would cost a microtask hop per call in
 * the tool-call hot path. Collisions are acceptable for a heuristic that only
 * ever nudges.
 */

const FNV_PRIME = 0x01000193
const LANE_A_OFFSET = 0x811c9dc5
const LANE_B_OFFSET = 0x050c5d1f
/** Lane B mixes in lane A shifted by this much, so the two lanes never stay equal. */
const LANE_MIX_SHIFT = 7
const HEX_RADIX = 16
const LANE_HEX_WIDTH = 8

/** Hashes `text` into a stable 16-hex-character id. */
export function hashText(text: string): string {
  let laneA = LANE_A_OFFSET
  let laneB = LANE_B_OFFSET
  for (let index = 0; index < text.length; index += 1) {
    const unit = text.charCodeAt(index)
    laneA = Math.imul(laneA ^ unit, FNV_PRIME)
    laneB = Math.imul(laneB ^ unit, FNV_PRIME) ^ (laneA >>> LANE_MIX_SHIFT)
  }
  return toHex(laneA) + toHex(laneB)
}

/** Fixed-width lowercase hex of an unsigned 32-bit lane. */
function toHex(lane: number): string {
  return (lane >>> 0).toString(HEX_RADIX).padStart(LANE_HEX_WIDTH, `0`)
}

