/**
 * Words: the model-facing nudge and the user-facing band copy for each
 * detector.
 *
 * Nudges follow prior-art messages: name the action, the count and the error,
 * then offer ways out, with asking the user always among them. They are
 * factual, never blaming, and tagged `[Loop Breaker]` so the transcript says
 * who wrote them. Band copy leads with numbers and stays one line.
 */
import { NUDGE_CAP, NUDGE_TAG, SNIPPET_CAP, TITLE_CAP } from './constants.ts'
import { truncate } from './normalize.ts'
import type { AlertCopy, ErrorClass, Signal } from './types.ts'

/** Human names for the environmental error classes. */
const CLASS_NAMES: Readonly<Record<ErrorClass, string>> = {
  'command-not-found': `a command that isn't installed`,
  permission: `a permission error`,
  network: `a service that isn't reachable`,
  auth: `failing authentication`,
  'rate-limit': `a rate limit`,
  'missing-module': `a missing package`,
  disk: `a full disk`,
  timeout: `commands timing out`,
}

/** Where a hint starts for each environmental class: the person finishes the sentence. */
const CLASS_HINTS: Readonly<Record<ErrorClass, (token: string | undefined) => string>> = {
  'command-not-found': token => `\`${token ?? `that command`}\` isn't available here. Use `,
  permission: () => `That path isn't writable for you here. Instead, `,
  network: () => `That service isn't running or reachable. `,
  auth: () => `Authentication is failing; the credentials need fixing outside the code. `,
  'rate-limit': () => `The API is rate-limiting us. Wait, or `,
  'missing-module': token => `\`${token ?? `that package`}\` isn't installed. `,
  disk: () => `The disk is full. `,
  timeout: () => `These commands keep timing out. `,
}

/** `: <snippet>` when the signal carries one, else nothing. */
function snippetSuffix(signal: Signal): string {
  return signal.snippet === undefined || signal.snippet === `` ? `` : `: ${signal.snippet}`
}

/** The environmental problem in words, naming the token when there is one. */
function problemOf(signal: Signal): string {
  // An MCP server's failure has no class; its label names the server.
  const name =
    signal.errorClass === undefined
      ? `the same problem with ${signal.label}`
      : CLASS_NAMES[signal.errorClass]
  return signal.errorToken === undefined ? name : `${name} (\`${signal.errorToken}\`)`
}

/** The model-facing note appended to the result of the call that revealed the loop. */
export function nudgeText(signal: Signal): string {
  const { count, label } = signal
  const text = ((): string => {
    switch (signal.detector) {
      case `repeat-failure`:
        return `${NUDGE_TAG} \`${label}\` has failed ${String(count)} times in a row with the same error${snippetSuffix(signal)}. Running it again won't change the result. Re-read the full error, state a new hypothesis and check it by reading the relevant code or adding a log. If something outside the code blocks you, ask the user.`
      case `same-error`:
        return `${NUDGE_TAG} The same error has come back ${String(count)} times across different attempts${snippetSuffix(signal)}. The changes so far are not reaching its cause. Find where the error originates and verify your hypothesis before the next fix, or ask the user.`
      case `cycle`:
        return `${NUDGE_TAG} The last ${String(count)} rounds repeated the same steps with the same results (${label}). Break the cycle with a different approach, or ask the user how to proceed.`
      case `edit-thrash`:
        return `${NUDGE_TAG} ${label} has gone back to an earlier version ${String(count)} times; the edits are undoing each other. Decide which version is right, and why, before editing it again, or ask the user.`
      case `denied-retry`:
        return `${NUDGE_TAG} The user declined \`${label}\` (${String(count)} attempts). Don't retry it. Ask the user how they want to proceed (AskUserQuestion), or choose a different approach.`
      case `env-blocker`:
        return `${NUDGE_TAG} ${String(count)} recent calls failed on ${problemOf(signal)}. Changing code won't fix this. Tell the user what is missing and ask how to proceed (AskUserQuestion) instead of retrying.`
      case `idle-repeat`:
        return `${NUDGE_TAG} \`${label}\` returned the same output ${String(count)} times with no change in between. You already have this information: use it, or do something different.`
      case `poll`:
        return `${NUDGE_TAG} \`${label}\` has returned the same output ${String(count)} times. Whatever it waits for isn't changing. Check why, wait longer between checks, or ask the user.`
    }
  })()
  return truncate(text, NUDGE_CAP)
}

/** The band copy for an escalated signal. */
export function alertCopy(signal: Signal): AlertCopy {
  const { count, label } = signal
  const times = `${String(count)}×`
  const copy = ((): AlertCopy => {
    switch (signal.detector) {
      case `repeat-failure`:
        return {
          title: `Claude seems stuck · \`${label}\` failed ${times} with the same error`,
          detail: signal.snippet ?? ``,
          hintTemplate: `Stop re-running \`${label}\`. First, `,
        }
      case `same-error`:
        return {
          title: `Claude seems stuck · the same error came back ${times} across attempts`,
          detail: signal.snippet ?? ``,
          hintTemplate: `The error keeps coming back. Look at `,
        }
      case `cycle`:
        return {
          title: `Claude is going in circles · the same steps repeated ${times}`,
          detail: label,
          hintTemplate: `You're repeating the same steps. Instead, `,
        }
      case `edit-thrash`:
        return {
          title: `Claude is undoing its own edits · ${label} reverted ${times}`,
          detail: ``,
          hintTemplate: `Keep the version where `,
        }
      case `denied-retry`:
        return {
          title: `Claude keeps retrying something you declined · \`${label}\` (${times})`,
          detail: signal.snippet ?? ``,
          hintTemplate: `Don't run \`${label}\`. Instead, `,
        }
      case `env-blocker`:
        return {
          title: `Claude can't fix this one · ${problemOf(signal)} (${times} across calls)`,
          detail: signal.snippet ?? ``,
          hintTemplate:
            signal.errorClass === undefined
              ? `This needs a change outside the code: `
              : CLASS_HINTS[signal.errorClass](signal.errorToken),
        }
      case `idle-repeat`:
        return {
          title: `Claude is repeating itself · \`${label}\` gave the same output ${times}`,
          detail: ``,
          hintTemplate: `You already have that output. Next, `,
        }
      case `poll`:
        return {
          title: `Claude is waiting on something that isn't changing · \`${label}\` (${times})`,
          detail: ``,
          hintTemplate: `Stop polling \`${label}\`. `,
        }
    }
  })()
  return {
    ...copy,
    title: truncate(copy.title, TITLE_CAP),
    detail: truncate(copy.detail, SNIPPET_CAP),
  }
}

